function formatTimestamp(value) {
  if (!value) {
    return "unknown time";
  }

  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) {
    return value;
  }

  return parsed.toLocaleString();
}

function localDateIso() {
  const now = new Date();
  const offsetMinutes = now.getTimezoneOffset();
  return new Date(now.getTime() - (offsetMinutes * 60 * 1000)).toISOString().slice(0, 10);
}

const DUTCH_DAY_NAMES = ["zondag", "maandag", "dinsdag", "woensdag", "donderdag", "vrijdag", "zaterdag"];

function dutchDayName(dateIso) {
  if (!dateIso) {
    return "";
  }
  const date = new Date(`${dateIso}T00:00:00`);
  if (Number.isNaN(date.getTime())) {
    return "";
  }
  const name = DUTCH_DAY_NAMES[date.getDay()] || "";
  return name ? `${name.charAt(0).toUpperCase()}${name.slice(1)}` : "";
}

// Standard ISO 8601 week number, matching the "week" column already used in
// the PD keuringen spreadsheet.
function isoWeekNumber(dateIso) {
  if (!dateIso) {
    return 0;
  }
  const date = new Date(`${dateIso}T00:00:00`);
  if (Number.isNaN(date.getTime())) {
    return 0;
  }
  const target = new Date(date.valueOf());
  const dayNr = (date.getDay() + 6) % 7;
  target.setDate(target.getDate() - dayNr + 3);
  const firstThursday = target.valueOf();
  target.setMonth(0, 1);
  if (target.getDay() !== 4) {
    target.setMonth(0, 1 + ((4 - target.getDay()) + 7) % 7);
  }
  return 1 + Math.round((firstThursday - target.valueOf()) / (7 * 24 * 3600 * 1000));
}

function normalizePermissions(role, permissions) {
  if (role === "admin") {
    return [...DEFAULT_PERMISSIONS_BY_ROLE.admin];
  }
  const defaults = DEFAULT_PERMISSIONS_BY_ROLE[role] || DEFAULT_PERMISSIONS_BY_ROLE.viewer;
  if (!Array.isArray(permissions)) {
    return [...defaults];
  }

  const normalized = [...new Set(
    permissions
      .map((value) => String(value || "").trim())
      .filter((value) => ALL_PERMISSIONS.includes(value)),
  )];

  return normalized.length ? normalized : [...defaults];
}

function hasPermission(user, permission) {
  if (!user) {
    return false;
  }

  const permissions = normalizePermissions(user.role, user.permissions);
  return permissions.includes(permission);
}

function availablePagesForUser(user) {
  return PAGE_DEFINITIONS.filter((page) => hasPermission(user, page.permission));
}

function defaultPageForUser(user) {
  return availablePagesForUser(user)[0]?.key || "dashboard";
}

