function imageUrl(image, run, retryKey = "") {
  const params = new URLSearchParams();
  params.set("id", image.id);
  params.set("account", String(run?.metadata?.drive_account || "default"));
  if (image.mime_type) {
    params.set("mime", image.mime_type);
  }
  if (retryKey) {
    params.set("retry", String(retryKey));
  }
  return `/api/image?${params.toString()}`;
}

function emitConnectionState(detail) {
  if (typeof window === "undefined") {
    return;
  }
  window.dispatchEvent(new CustomEvent("shadow-connection-state", { detail }));
}

function PhotoImage({ image, run, alt, loading = "eager" }) {
  const [attempt, setAttempt] = useState(0);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    setAttempt(0);
    setFailed(false);
  }, [image.id, run?.folder_id]);

  useEffect(() => {
    if (!failed || attempt >= 3) {
      return undefined;
    }

    const timer = window.setTimeout(() => {
      setFailed(false);
      setAttempt((value) => value + 1);
    }, 1200);

    return () => window.clearTimeout(timer);
  }, [attempt, failed]);

  return (
    <img
      src={imageUrl(image, run, attempt)}
      alt={alt}
      loading={loading}
      onError={() => setFailed(true)}
    />
  );
}

// Requests on their way: the loading bar (top of the page) shows while one
// takes longer than a moment.
let apiRequestsInFlight = 0;
const apiLoadingListeners = new Set();

function setApiRequestsInFlight(change) {
  apiRequestsInFlight = Math.max(0, apiRequestsInFlight + change);
  for (const listener of apiLoadingListeners) listener(apiRequestsInFlight);
}

function ApiLoadingBar() {
  const [busy, setBusy] = useState(false);
  useEffect(() => {
    let timer = null;
    const listener = (count) => {
      window.clearTimeout(timer);
      if (count > 0) timer = window.setTimeout(() => setBusy(true), 350);
      else setBusy(false);
    };
    apiLoadingListeners.add(listener);
    return () => { apiLoadingListeners.delete(listener); window.clearTimeout(timer); };
  }, []);
  return busy ? <div className="api-loading-bar" role="progressbar" aria-label="Loading" /> : null;
}

async function apiJson(path, options = {}) {
  setApiRequestsInFlight(1);
  try {
    return await apiJsonRequest(path, options);
  } finally {
    setApiRequestsInFlight(-1);
  }
}

async function apiJsonRequest(path, options = {}) {
  let response;
  try {
    response = await fetch(path, {
      ...options,
      headers: {
        ...(options.body ? { "content-type": "application/json" } : {}),
        ...(options.headers || {}),
      },
    });
  } catch (error) {
    emitConnectionState({
      connected: false,
      message: "Connection lost. The app may be updating or restarting.",
      source: "api",
    });
    throw error;
  }
  const payload = await response.json().catch(() => ({}));
  if (response.ok) {
    emitConnectionState({ connected: true, source: "api" });
  } else if ([502, 503, 504].includes(response.status)) {
    emitConnectionState({
      connected: false,
      message: "Connection lost. The app may be updating or restarting.",
      source: "api",
    });
  }
  if (!response.ok) {
    throw new Error(payload.error || `Request failed with ${response.status}`);
  }
  return payload;
}

function useHeartbeatMonitor(enabled) {
  const [state, setState] = useState({
    connected: true,
    message: "",
    failures: 0,
    lastOkAt: new Date().toISOString(),
  });

  useEffect(() => {
    if (!enabled) {
      return undefined;
    }

    let stopped = false;
    let failureCount = 0;
    let lastOkAtMs = Date.now();

    function markConnected() {
      failureCount = 0;
      lastOkAtMs = Date.now();
      if (!stopped) {
        setState({
          connected: true,
          message: "",
          failures: 0,
          lastOkAt: new Date(lastOkAtMs).toISOString(),
        });
      }
    }

    function markDisconnected(message) {
      failureCount += 1;
      const staleForMs = Date.now() - lastOkAtMs;
      const shouldDisconnect = failureCount >= HEARTBEAT_FAILURES_BEFORE_OVERLAY
        && staleForMs >= HEARTBEAT_STALE_MS_BEFORE_OVERLAY;
      if (!stopped) {
        setState((current) => ({
          connected: shouldDisconnect ? false : current.connected,
          message: shouldDisconnect ? (message || "Connection lost. The app may be updating or restarting.") : current.message,
          failures: failureCount,
          lastOkAt: current.lastOkAt,
        }));
      }
    }

    async function checkHeartbeat() {
      if (typeof document !== "undefined" && document.hidden) {
        return;
      }
      try {
        const response = await fetch(`/api/status?_ts=${Date.now()}`, { cache: "no-store" });
        if (!response.ok) {
          throw new Error(`Heartbeat failed with ${response.status}`);
        }
        markConnected();
      } catch {
        markDisconnected("Connection lost. The app may be updating or restarting.");
      }
    }

    function handleOnline() {
      checkHeartbeat();
    }

    function handleOffline() {
      failureCount = Math.max(failureCount, HEARTBEAT_FAILURES_BEFORE_OVERLAY);
      if (!stopped) {
        setState((current) => ({
          connected: false,
          message: "Connection lost. This device is offline.",
          failures: failureCount,
          lastOkAt: current.lastOkAt,
        }));
      }
    }

    function handleConnectionEvent(event) {
      const detail = event?.detail || {};
      if (detail.connected) {
        markConnected();
        return;
      }
      failureCount = Math.max(failureCount + 1, HEARTBEAT_FAILURES_BEFORE_OVERLAY);
      if (!stopped) {
        setState((current) => ({
          connected: false,
          message: detail.message || "Connection lost. The app may be updating or restarting.",
          failures: failureCount,
          lastOkAt: current.lastOkAt,
        }));
      }
    }

    if (typeof navigator !== "undefined" && navigator.onLine === false) {
      handleOffline();
    } else {
      checkHeartbeat();
    }

    const interval = window.setInterval(checkHeartbeat, HEARTBEAT_INTERVAL_MS);
    window.addEventListener("online", handleOnline);
    window.addEventListener("offline", handleOffline);
    window.addEventListener("shadow-connection-state", handleConnectionEvent);

    return () => {
      stopped = true;
      window.clearInterval(interval);
      window.removeEventListener("online", handleOnline);
      window.removeEventListener("offline", handleOffline);
      window.removeEventListener("shadow-connection-state", handleConnectionEvent);
    };
  }, [enabled]);

  return state;
}

