// Eric Docs' check: does the temporary phyto PDF's printed pieces total
// match the inspection list's printed pieces total -- and, when PD Keuring's
// own "Pieces" field is filled in for this zending, that both also agree
// with it. Deliberately simpler than UKDocs CSI -- no XML/IPAFFS cross-check,
// just these two PDFs (plus that one optional manual figure).
function ericDocsCheckStatus(check) {
  if (!check?.checked_at) {
    return { tone: "warn", label: "Not checked yet" };
  }
  if (!check.ok) {
    return { tone: "danger", label: check.error || "Could not run the check" };
  }
  if (check.match) {
    return {
      tone: "success",
      label: check.expected_pieces !== null
        ? `Pieces match (${check.phyto_total}, PD Keuring expects ${check.expected_pieces})`
        : `Pieces match (${check.phyto_total})`,
    };
  }
  return { tone: "danger", label: check.error || `MISMATCH: phyto ${check.phyto_total} vs inspection ${check.inspection_total}` };
}

// One honest view over the invoice-generate -> PDF-convert -> CSI-audit ->
// papers-sent pipeline for a day's shipments -- built after two confirmed
// stuck-job bugs (invoice PDFs and CSI audits both silently never retrying)
// so a stuck step is visible immediately here instead of only being
// discovered when a shipment fails to actually go out. Polls every 30s
// while open; the server-side watchdogs (every 3 min) do the actual fixing,
// this just makes sure nobody has to find out by accident.
// Shelf count health in the Pipeline Monitor: last night's run, its queue
// and the shelf poller's heartbeat. Hidden for users without shelf-count access.
function ShelfCountMonitorCard({ date }) {
  const [data, setData] = useState(null);
  const [hidden, setHidden] = useState(false);
  // The night run counts the photos OF a date -- show the run for the
  // monitor's date and, by default, last night's.
  const [runDate, setRunDate] = useState(() => addDaysToIso(date, -1));
  useEffect(() => { setRunDate(addDaysToIso(date, -1)); }, [date]);

  useEffect(() => {
    let cancelled = false;
    const load = () => apiJson(`/api/shelf-count/monitor?date=${runDate}`)
      .then((payload) => { if (!cancelled) setData(payload); })
      .catch((loadError) => { if (!cancelled && /403|permission/i.test(loadError.message)) setHidden(true); });
    load();
    const interval = setInterval(load, 30000);
    return () => { cancelled = true; clearInterval(interval); };
  }, [runDate]);

  if (hidden || !data) return null;
  const run = data.run;
  const tone = !run ? "muted" : data.stale ? "danger" : run.status === "done" ? "success" : run.status === "failed" ? "danger" : "info";
  const label = !run ? "not started" : data.stale ? `stuck -- no progress for ${run.quiet_minutes} min (auto-resumes after ${data.stale_after_minutes})` : run.status;
  const pollerText = data.pollers.length
    ? data.pollers.map((poller) => `${poller.agent_name}: ${poller.status}${poller.last_seen_minutes !== null ? `, seen ${poller.last_seen_minutes} min ago` : ""}`).join(" | ")
    : "no shelf poller has reported in";
  const shelves = data.accuracy?.shelves;
  return (
    <div className="data-table-card">
      <div className="section-header"><h2>Shelf count</h2></div>
      <div className="row-actions">
        <label><span>Photos of</span><input type="date" value={runDate} onChange={(event) => setRunDate(event.target.value)} /></label>
      </div>
      <div className="table-wrap">
        <table className="data-table">
          <tbody>
            <tr><td>Night run</td><td><span className={`ukdocs-status-badge ${tone}`}>{label}</span>{run?.started_at ? ` -- started ${new Date(run.started_at).toLocaleString("nl-NL")}` : ""}</td></tr>
            <tr><td>References</td><td>{data.references} -- {Object.entries(data.by_status).map(([status, count]) => `${count} ${status}`).join(", ") || "none yet"}</td></tr>
            <tr><td>Count jobs waiting</td><td>{data.queued_jobs} queued, {data.claimed_jobs} being counted{data.oldest_queued_minutes !== null ? ` (oldest waiting ${data.oldest_queued_minutes} min)` : ""}</td></tr>
            <tr><td>Shelf poller (GPU PC)</td><td>{pollerText}</td></tr>
            <tr><td>Shelves vs Fust (DCS)</td><td>{shelves?.compared ? `${shelves.exact_rate}% exactly right (${shelves.exact}/${shelves.compared}), off ${shelves.mean_abs_diff} on average` : "nothing to compare yet"}</td></tr>
          </tbody>
        </table>
      </div>
    </div>
  );
}

// The background invoice-vs-ERP comparison (one day at a time, stored):
// how many days are waiting / running / failed. Polls faster while busy.
function useInkoopMatchStatus() {
  const [status, setStatus] = useState(null);
  useEffect(() => {
    let cancelled = false;
    let timer = null;
    const load = () => apiJson("/api/inkoop/match-status")
      .then((payload) => { if (!cancelled) setStatus(payload); return payload; })
      .catch(() => null)
      .then((payload) => {
        if (cancelled) return;
        const busy = payload && ((payload.counts?.pending || 0) + (payload.counts?.running || 0)) > 0;
        timer = setTimeout(load, busy ? 5000 : 30000);
      });
    load();
    return () => { cancelled = true; clearTimeout(timer); };
  }, []);
  return [status, setStatus];
}

function inkoopMatchBusyCount(status) {
  return (status?.counts?.pending || 0) + (status?.counts?.running || 0);
}

// The daily invoice-email import (Gmail -> Inkoop Controle): its settings,
// "Run now" for a date, and what each run did. In the Pipeline Monitor and
// in Inkoop's Settings.
function InkoopMailImportCard({ editable = true }) {
  const [data, setData] = useState(null);
  const [hidden, setHidden] = useState(false);
  const [draft, setDraft] = useState(null);
  const [runDate, setRunDate] = useState(() => localDateIso());
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [openRun, setOpenRun] = useState(null);
  function load() {
    return apiJson("/api/inkoop/mail-import")
      .then((payload) => { setData(payload); setDraft((current) => current || payload.settings); })
      .catch((loadError) => { if (/403|permission/i.test(loadError.message)) setHidden(true); else setError(loadError.message); });
  }
  useEffect(() => {
    load();
    const interval = setInterval(load, 30000);
    return () => clearInterval(interval);
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
  if (hidden || !data || !draft) return null;
  async function save() {
    setBusy(true);
    setError("");
    try {
      const payload = await apiJson("/api/inkoop/mail-import/settings", { method: "POST", body: JSON.stringify({ settings: draft }) });
      setDraft(payload.settings);
      setMessage("Saved.");
      await load();
    } catch (saveError) {
      setError(saveError.message);
    } finally {
      setBusy(false);
    }
  }
  async function runNow() {
    setBusy(true);
    setError("");
    setMessage(`Importing the invoice emails of ${fustOverviewDate(runDate)}...`);
    try {
      const payload = await apiJson("/api/inkoop/mail-import/run", { method: "POST", body: JSON.stringify({ date: runDate }) });
      setMessage(payload.skipped ? payload.reason : `${payload.emails_new} new email(s) of ${payload.emails_found}: ${payload.invoices} invoice(s), ${payload.invoice_lines} lines, ${payload.pdfs} PDF(s).`);
      await load();
    } catch (runError) {
      setError(runError.message);
      setMessage("");
    } finally {
      setBusy(false);
    }
  }
  const last = data.runs[0];
  const tone = (run) => (run.status === "done" ? "success" : run.status === "failed" ? "danger" : "info");
  return (
    <div className="data-table-card">
      <div className="section-header"><h2>Inkoop Controle -- invoice emails (Gmail)</h2></div>
      <div className="notice">
        The invoice emails forwarded to the UKdocs mailbox ({data.gmail_connected ? data.gmail_email || "connected" : "Gmail not connected -- connect it in UKdocs"}) are imported to Inkoop Controle every day at {draft.time}: all of that day's FloraHolland and AI2 invoice emails not imported before. The UKdocs papers in the same mailbox stay with UKdocs. Uploading by hand still works as always.
      </div>
      <div className="row-actions">
        <span className={`ukdocs-status-badge ${data.settings.enabled ? "success" : "muted"}`}>{data.settings.enabled ? `on, daily at ${data.settings.time}` : "off"}</span>
        {last ? <span className={`ukdocs-status-badge ${tone(last)}`}>last run {fustOverviewDate(last.run_date)}: {last.status}</span> : <span className="muted">no run yet</span>}
        {data.busy && <span className="ukdocs-status-badge info">importing now...</span>}
        <label><span>Date</span><input type="date" value={runDate} onChange={(event) => setRunDate(event.target.value)} /></label>
        <button type="button" onClick={runNow} disabled={busy || data.busy || !data.gmail_connected}>{busy ? "Importing..." : "Run now"}</button>
      </div>
      {editable && (
        <details style={{ margin: "6px 0" }}>
          <summary>Settings</summary>
          <div className="form-grid" style={{ marginTop: 6 }}>
            <label className="checkbox-label"><input type="checkbox" checked={draft.enabled} onChange={(event) => setDraft((current) => ({ ...current, enabled: event.target.checked }))} /><span>Import every day</span></label>
            <label><span>Time (Dutch time)</span><input type="time" value={draft.time} onChange={(event) => setDraft((current) => ({ ...current, time: event.target.value }))} /></label>
            <label className="wide"><span>Which emails (Gmail search)</span><input value={draft.query} onChange={(event) => setDraft((current) => ({ ...current, query: event.target.value }))} /></label>
          </div>
          <div className="row-actions"><button type="button" className="primary" onClick={save} disabled={busy}>Save</button></div>
        </details>
      )}
      {message && <div className="notice info">{message}</div>}
      {error && <div className="notice danger">{error}</div>}
      {!!data.runs.length && (
        <div className="table-wrap">
          <table className="data-table">
            <thead><tr><th>Day</th><th>Started</th><th>How</th><th>Status</th><th>Emails (new / found)</th><th>Invoices</th><th>Lines</th><th>PDFs</th><th>Skipped</th></tr></thead>
            <tbody>
              {data.runs.map((run) => (
                <Fragment key={run.id}>
                  <tr>
                    <td>{fustOverviewDate(run.run_date)}</td>
                    <td>{formatTimestamp(run.started_at)}</td>
                    <td>{run.trigger === "auto" ? "daily" : `by hand (${run.created_by})`}</td>
                    <td><span className={`ukdocs-status-badge ${tone(run)}`}>{run.status}</span>{run.error_text ? <div className="muted">{run.error_text}</div> : null}</td>
                    <td>{run.emails_new} / {run.emails_found}</td>
                    <td>{run.invoices}</td>
                    <td>{run.invoice_lines}</td>
                    <td>{run.pdfs}</td>
                    <td>{(run.skipped || []).length ? <button type="button" className="link-button" onClick={() => setOpenRun((current) => (current === run.id ? null : run.id))}>{(run.skipped || []).length} -- {openRun === run.id ? "hide" : "show"}</button> : "-"}</td>
                  </tr>
                  {openRun === run.id && (
                    <tr><td colSpan={9}>{(run.skipped || []).map((item, index) => <div key={index} className="muted">{item.subject || item.file_name}: {item.reason}</div>)}</td></tr>
                  )}
                </Fragment>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function InkoopMatchMonitorCard() {
  const [status, setStatus] = useInkoopMatchStatus();
  const [retrying, setRetrying] = useState(false);
  if (!status) return null;
  const counts = status.counts || {};
  async function retry() {
    setRetrying(true);
    try {
      setStatus(await apiJson("/api/inkoop/match-retry", { method: "POST", body: "{}" }));
    } finally {
      setRetrying(false);
    }
  }
  return (
    <div className="data-table-card">
      <div className="section-header"><h2>Inkoop Controle -- background comparison</h2></div>
      <div className="notice">
        Every day is compared (invoices vs Connect) once in the background and stored; the Inkoop tabs only read it. An upload or a master-data change queues the days it affects.
      </div>
      <div className="row-actions">
        <span className="ukdocs-status-badge success">{counts.ready || 0} ready</span>
        <span className={`ukdocs-status-badge ${inkoopMatchBusyCount(status) ? "info" : "muted"}`}>{counts.pending || 0} waiting</span>
        <span className={`ukdocs-status-badge ${counts.running ? "info" : "muted"}`}>{counts.running ? `busy: ${status.running.join(", ")}` : "nothing running"}</span>
        <span className={`ukdocs-status-badge ${counts.failed ? "danger" : "muted"}`}>{counts.failed || 0} failed</span>
        {status.average_ms ? <span className="muted">{status.average_ms < 1000 ? "under 1 s per day" : `about ${Math.round(status.average_ms / 1000)} s per day`}</span> : null}
        {status.last_computed_at ? <span className="muted">last: {formatTimestamp(status.last_computed_at)}</span> : null}
        {!!counts.failed && <button type="button" onClick={retry} disabled={retrying}>{retrying ? "Retrying..." : "Retry failed days"}</button>}
      </div>
      {!!status.failed?.length && (
        <div className="table-wrap">
          <table className="data-table">
            <thead><tr><th>Day</th><th>Tries</th><th>Error</th></tr></thead>
            <tbody>
              {status.failed.map((row) => <tr key={row.date}><td>{fustOverviewDate(row.date)}</td><td>{row.attempts}</td><td>{row.error_text}</td></tr>)}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}

function UkdocsPipelineMonitorPage({ onNavigate }) {
  const [date, setDate] = useState(() => localDateIso());
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [onlyAttention, setOnlyAttention] = useState(false);

  function load() {
    setError("");
    const params = new URLSearchParams({ date });
    return apiJson(`/api/ukdocs-print/pipeline-monitor?${params.toString()}`)
      .then((payload) => setData(payload))
      .catch((loadError) => setError(loadError.message))
      .finally(() => setLoading(false));
  }

  useEffect(() => {
    setLoading(true);
    load().catch(() => {});
    const interval = setInterval(() => {
      load().catch(() => {});
    }, 30000);
    return () => clearInterval(interval);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [date]);

  function openShipment(row) {
    requestUkdocsPrintOpen(row.collection_id, date);
    onNavigate?.("ukdocsprint");
  }

  if (loading && !data) {
    return <div className="notice">Loading pipeline monitor...</div>;
  }

  const rows = (data?.rows || []).filter((row) => !onlyAttention || row.needs_attention);

  return (
    <section className="overview-stack">
      <div className="row-actions spread-actions">
        <label>
          <span>Date</span>
          <input type="date" value={date} onChange={(event) => setDate(event.target.value)} />
        </label>
        <label>
          <input type="checkbox" checked={onlyAttention} onChange={(event) => setOnlyAttention(event.target.checked)} />
          <span> Only show what needs attention</span>
        </label>
        <button type="button" onClick={() => load()}>Refresh now</button>
      </div>

      {error && <div className="notice danger">{error}</div>}

      <ShelfCountMonitorCard date={date} />

      <InkoopMatchMonitorCard />
      <InkoopMailImportCard editable={false} />
      <InkoopDataDaysMonitorLine />

      {data && (
        <div className="notice">
          {data.summary.total} shipments for {data.date} -- {data.summary.needs_attention} need attention, {data.summary.stale_jobs} job(s) stuck past their retry threshold (auto-retried every 3 minutes). Refreshes automatically every 30 seconds.
        </div>
      )}

      <div className="data-table-card">
        <div className="table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th>Shipment</th>
                <th>What's left</th>
                <th>CSI</th>
                <th>Active jobs</th>
                <th>Papers sent</th>
                <th>Status</th>
                <th></th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => (
                <tr key={row.collection_id}>
                  <td>
                    <strong>{row.customer_name}</strong>
                    <br />
                    <small>{row.city_name}{row.reference_connect ? ` · Connect ${row.reference_connect}` : ""}{row.invoice_numbers ? ` · Invoices ${row.invoice_numbers}` : ""}</small>
                  </td>
                  <td>
                    {row.complete
                      ? <span className="ukdocs-status-badge success">Complete</span>
                      : row.missing.map((item, index) => <div key={index}><small>{item}</small></div>)}
                  </td>
                  <td>
                    {row.csi_status
                      ? (
                        <span className={`ukdocs-status-badge ${row.csi_status === "done" ? "success" : (row.csi_status === "failed" || row.csi_orphaned) ? "danger" : "info"}`}>
                          {row.csi_status}{row.csi_elapsed_minutes !== null ? ` (${row.csi_elapsed_minutes}m)` : ""}
                        </span>
                      )
                      : "-"}
                  </td>
                  <td>
                    {row.active_jobs.length
                      ? row.active_jobs.map((job, index) => (
                        <div key={index}>
                          <small>
                            {job.job_type === "excel_to_pdf" ? "Invoice PDF" : "CSI audit"} · {job.status} · {job.elapsed_minutes}m
                            {job.stale ? " -- stuck" : ""}
                          </small>
                        </div>
                      ))
                      : "-"}
                  </td>
                  <td>
                    {row.papers_sent
                      ? <span className="ukdocs-status-badge success" title={row.papers_note || ""}>Sent</span>
                      : (
                        <>
                          <span className={`ukdocs-status-badge ${row.papers_status === "failed" ? "danger" : "muted"}`} title={row.papers_note || ""}>
                            {row.papers_status === "failed" ? "Send failed" : row.papers_status === "off" ? "Off for customer" : row.papers_status === "queued" ? "Sending soon" : "Not sent"}
                          </span>
                          {row.papers_note ? <small className="ukdocs-papers-note">{row.papers_note}</small> : null}
                        </>
                      )}
                  </td>
                  <td>
                    {row.needs_attention
                      ? <span className="ukdocs-status-badge danger" title={row.attention_reasons.join("; ")}>Needs attention</span>
                      : <span className="ukdocs-status-badge success">OK</span>}
                  </td>
                  <td><button type="button" onClick={() => openShipment(row)}>Open</button></td>
                </tr>
              ))}
              {!rows.length && (
                <tr><td colSpan={7}>{onlyAttention ? "Nothing needs attention right now." : "No shipments for this date."}</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </section>
  );
}

// Mirrors localDateIso()'s own offset trick rather than re-parsing its
// "YYYY-MM-DD" string output as a Date (which parses as UTC midnight and
// would drift a day off in negative-UTC-offset timezones).
function shelfCountYesterdayIso() {
  const now = new Date();
  const offsetMinutes = now.getTimezoneOffset();
  const localNow = new Date(now.getTime() - offsetMinutes * 60 * 1000);
  localNow.setUTCDate(localNow.getUTCDate() - 1);
  return localNow.toISOString().slice(0, 10);
}

const SHELF_COUNT_STATUS_TONE = {
  done: "success",
  pending: "info",
  processing: "info",
  needs_review: "danger",
  failed: "danger",
  missing_photos: "muted",
  combined: "muted",
};

// expected_average/deviation are filled in by the Fust shadow job (server
// side, see applyFustShadowForDate) wherever a reference's Fust Planning
// Code data is also available for the same date -- shadow/observation only,
// starting 2026-10-01, so these stay blank for anything before that or with
// no Fust match.
// Counted minus expected, shown with a sign ("+1", "-2", "0"); "-" when
// either side is missing. Coloured when it's off.
function shelfDiffCell(counted, expected) {
  if (counted === null || counted === undefined || counted === "" || expected === null || expected === undefined || expected === "") {
    return <td>-</td>;
  }
  const diff = Number(counted) - Number(expected);
  return <td style={{ color: diff ? "var(--x-b45309)" : "var(--x-15803d)", fontWeight: 600 }}>{diff > 0 ? `+${diff}` : diff}</td>;
}

// "4 ext. · 4-6 shelves" from the Halindeling volume (see the server's
// estimateFromVolume), flagged when the photo count falls outside it.
function shelfVolumeCell(row) {
  const estimate = row.volume_estimate;
  if (!estimate) {
    return <td>-</td>;
  }
  const range = (low, high) => (low === high ? `${low}` : `${low}-${high}`);
  const outside = (value, low, high) => value !== null && value !== undefined && value !== "" && (Number(value) < low || Number(value) > high);
  const photoLevels = row.level_count ?? row.shelf_count;
  const warnings = [];
  if (outside(row.extension_count, estimate.extensions_min, estimate.extensions_max)) {
    warnings.push(`photo says ${row.extension_count} extensions`);
  }
  if (outside(photoLevels, estimate.shelves_min, estimate.shelves_max)) {
    warnings.push(`photo says ${photoLevels} shelves`);
  }
  return (
    <td title={`Volume ${estimate.volume} over ${estimate.trolleys} trolley(s); last trolley ${Math.round(estimate.last_fill * 100)}% full. Below 45% no extensions, from 80% extensions, in between undecided.`}>
      <div style={{ fontWeight: 600 }}>{range(estimate.extensions_min, estimate.extensions_max)} ext. · {range(estimate.shelves_min, estimate.shelves_max)} shelves</div>
      <div className="muted">vol. {estimate.volume} · last {Math.round(estimate.last_fill * 100)}%</div>
      {warnings.length ? <div style={{ color: "var(--x-b45309)", fontWeight: 600 }}>{warnings.join(", ")}</div> : null}
    </td>
  );
}

function ShelfAccuracySummary({ accuracy }) {
  if (!accuracy) return null;
  const row = (label, stats) => (
    <tr key={label}>
      <td>{label}</td>
      <td>{stats?.compared ? `${stats.exact_rate}%` : "-"}</td>
      <td>{stats?.compared ? `${stats.exact} / ${stats.compared}` : "-"}</td>
      <td>{stats?.compared ? stats.mean_abs_diff : "-"}</td>
    </tr>
  );
  return (
    <div className="data-table-card">
      <div className="section-header"><h3>How correct vs Fust Planning</h3></div>
      <div className="notice">Compared with what Fust Planning reports for the same references: DC = trolleys, DCS = shelves, DCO = extensions. Only references where both sides have a number are compared.</div>
      <div className="table-wrap">
        <table className="data-table">
          <thead><tr><th>What</th><th>Exactly right</th><th>Right / compared</th><th>Off on average</th></tr></thead>
          <tbody>
            {row("Trolleys (RFID scan vs DC)", accuracy.trolleys)}
            {row("Shelves -- official count (vs DCS)", accuracy.shelves)}
            {row("Shelves -- trained model (vs DCS)", accuracy.shelves_trained_model)}
            {row("Extensions -- official count (vs DCO)", accuracy.extensions)}
            {row("Extensions -- trained model (vs DCO)", accuracy.extensions_trained_model)}
            {row("Extensions -- from volume, where decided (vs DCO)", accuracy.extensions_volume)}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function ShelfCountPage() {
  const [date, setDate] = useState(() => shelfCountYesterdayIso());
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [rerunning, setRerunning] = useState(false);
  const [error, setError] = useState("");
  const [message, setMessage] = useState("");

  function load() {
    setError("");
    return apiJson(`/api/shelf-count/nightly-run?date=${encodeURIComponent(date)}`)
      .then((payload) => setData(payload))
      .catch((loadError) => setError(loadError.message))
      .finally(() => setLoading(false));
  }

  useEffect(() => {
    setLoading(true);
    load().catch(() => {});
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [date]);

  async function rerunForDate() {
    setRerunning(true);
    setError("");
    setMessage("");
    try {
      const result = await apiJson("/api/shelf-count/nightly-run", {
        method: "POST",
        body: JSON.stringify({ date }),
      });
      setMessage(result.skipped ? `Already run for ${date} (${result.skipped}).` : `Re-ran ${date}: ${JSON.stringify(result.totals)}`);
      await load();
    } catch (rerunError) {
      setError(rerunError.message);
    } finally {
      setRerunning(false);
    }
  }

  // Recomputes the Fust Planning columns for this date (automatic only for
  // the last two days).
  async function refreshFustComparison() {
    setRerunning(true);
    setError("");
    setMessage("");
    try {
      const result = await apiJson("/api/shelf-count/fust-shadow/run", { method: "POST", body: JSON.stringify({ date }) });
      const summary = (result.summaries || [])[0] || {};
      setMessage(summary.skipped ? `Fust comparison skipped: ${summary.reason}` : `Fust comparison updated for ${date}: ${summary.matched ?? 0} of ${summary.checked ?? 0} references found in Fust Planning.`);
      await load();
    } catch (refreshError) {
      setError(refreshError.message);
    } finally {
      setRerunning(false);
    }
  }

  const run = data?.run;
  const counts = data?.counts || [];

  if (loading && !data) {
    return <div className="notice">Loading shelf count...</div>;
  }

  return (
    <section className="overview-stack">
      <div className="row-actions spread-actions">
        <label>
          <span>Date</span>
          <input type="date" value={date} onChange={(event) => setDate(event.target.value)} />
        </label>
        <button type="button" onClick={rerunForDate} disabled={rerunning}>
          {rerunning ? "Running..." : "Re-run for this date"}
        </button>
        <button type="button" onClick={refreshFustComparison} disabled={rerunning}>
          Update Fust comparison
        </button>
      </div>

      {message && <div className="notice">{message}</div>}
      {error && <div className="notice danger">{error}</div>}

      <div className="notice">
        {run
          ? (
            <>
              Run status: <span className={`ukdocs-status-badge ${run.status === "done" ? "success" : run.status === "failed" ? "danger" : "info"}`}>{run.status}</span>
              {" -- "}{(run.totals?.checked ?? 0)} checked, {(run.totals?.ok ?? 0)} ok, {(run.totals?.needs_review ?? 0)} needs review,{" "}
              {(run.totals?.failed ?? 0)} failed, {(run.totals?.missing_photos ?? 0)} missing photos, {(run.totals?.unmatched_folder ?? 0)} unmatched folders.
            </>
          )
          : "No nightly run recorded for this date yet."}
      </div>

      {!!run?.issues?.length && (
        <div className="data-table-card">
          <div className="section-header"><h3>Issues ({run.issues.length})</h3></div>
          <div className="table-wrap">
            <table className="data-table">
              <thead><tr><th>Type</th><th>Customer reference</th><th>Folder</th></tr></thead>
              <tbody>
                {run.issues.map((issue, index) => (
                  <tr key={index}>
                    <td>{issue.type}</td>
                    <td>{issue.customer_reference || "-"}</td>
                    <td>{issue.folder_name || "-"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}

      <ShelfAccuracySummary accuracy={data?.accuracy} />

      <div className="data-table-card">
        <div className="section-header"><h2>References ({counts.length})</h2></div>
        <div className="table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th />
                <th colSpan={8} style={{ textAlign: "center", background: "var(--x-e0f2fe)" }}>Counted from the photos (RFID scan + shelf count)</th>
                <th colSpan={7} style={{ textAlign: "center", background: "var(--x-fef3c7)" }}>Fust Planning (expected) and difference (counted - Fust)</th>
                <th style={{ textAlign: "center", background: "var(--x-dcfce7)" }}>Halindeling volume</th>
                <th colSpan={2} />
              </tr>
              <tr>
                <th>Customer reference</th><th>Trolleys</th><th>Photos</th><th>Shelves</th><th>Levels</th>
                <th>Extensions</th><th>Per trolley (shelves / levels / ext.)</th><th>Trained model (shelves / ext.)</th><th>Confidence</th>
                <th>Fust trolleys (DC)</th><th>Trolley diff</th>
                <th>Fust shelves (DCS)</th><th>Shelf diff (levels - DCS)</th><th>Trained model shelf diff</th>
                <th>Fust extensions (DCO)</th><th>Ext. diff</th><th>Expected from volume</th><th>Status</th><th>Error</th>
              </tr>
            </thead>
            <tbody>
              {counts.map((row) => (
                <tr key={row.customer_reference}>
                  <td>{row.customer_reference}</td>
                  <td>{row.trolley_count}</td>
                  <td>{row.photo_count}</td>
                  <td>{row.shelf_count ?? "-"}</td>
                  <td>{row.level_count ?? "-"}</td>
                  <td>{row.extension_count ?? "-"}</td>
                  <td>
                    {Array.isArray(row.per_trolley) && row.per_trolley.length
                      ? row.per_trolley.map((entry, index) => (
                        <div key={index}>T{entry.trolley ?? index + 1}: {entry.shelves ?? "-"} / {entry.levels ?? "-"} / {entry.extensions ?? "-"}</div>
                      ))
                      : "-"}
                  </td>
                  <td>
                    {row.trained_model?.error
                      ? <span className="muted" title={row.trained_model.error}>error</span>
                      : row.trained_model
                        ? (
                          <span
                            title={`Model ${row.trained_model.model_version || "?"}, confidence ${row.trained_model.confidence ?? "-"}; per photo: ${(row.trained_model.per_photo || []).map((photo) => `${photo.shelf_level}/${photo.extension}`).join(", ")} (median x ${row.trained_model.trolley_count} trolleys)`}
                            style={{ color: row.shelf_count !== null && row.shelf_count !== undefined && Number(row.shelf_count) !== Number(row.trained_model.shelf_count) ? "var(--x-b45309)" : undefined, fontWeight: 600 }}
                          >
                            {row.trained_model.shelf_count} / {row.trained_model.extension_count}
                          </span>
                        )
                        : "-"}
                  </td>
                  <td>{row.confidence !== null && row.confidence !== undefined ? Number(row.confidence).toFixed(2) : "-"}</td>
                  <td>{row.expected_trolleys ?? "-"}</td>
                  {shelfDiffCell(row.trolley_count, row.expected_trolleys)}
                  <td>{row.expected_average ?? "-"}</td>
                  {shelfDiffCell(row.level_count ?? row.shelf_count, row.expected_average)}
                  {shelfDiffCell(row.trained_model && !row.trained_model.error ? row.trained_model.shelf_count : null, row.expected_average)}
                  <td>{row.extension_expected ?? "-"}</td>
                  {shelfDiffCell(row.extension_count, row.extension_expected)}
                  {shelfVolumeCell(row)}
                  <td>
                    <span className={`ukdocs-status-badge ${SHELF_COUNT_STATUS_TONE[row.status] || "muted"}`}>{row.status}</span>
                    {row.combined_into ? <div className="muted">photographed with {row.combined_into}</div> : null}
                  </td>
                  <td>{row.error_text || "-"}</td>
                </tr>
              ))}
              {!counts.length && <tr><td colSpan={20}>No completed references for this date.</td></tr>}
            </tbody>
          </table>
        </div>
      </div>
    </section>
  );
}

function EricDocsPage({ currentUser }) {
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [state, setState] = useState(null);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [selectedCollectionDate, setSelectedCollectionDate] = useState(() => pdStepPlanFocus("ericdocs")?.date || localDateIso());
  const [selectedCollectionId, setSelectedCollectionId] = useState(() => pdStepPlanFocus("ericdocs")?.collection_id || "");
  const [detailDrawerOpen, setDetailDrawerOpen] = useState(false);

  useEffect(() => {
    let cancelled = false;
    apiJson("/api/ukdocs/state")
      .then((payload) => {
        if (!cancelled) {
          setState(payload.state);
        }
      })
      .catch((loadError) => {
        if (!cancelled) {
          setError(loadError.message);
        }
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false);
        }
      });
    return () => {
      cancelled = true;
    };
  }, [currentUser]);

  const collections = state?.print_collections || [];
  const customers = state?.customers || [];
  const shipmentCollections = useMemo(
    () => collections.filter((item) => {
      if (item.collection_type === "stock_control") {
        return false;
      }
      const customer = ukdocsPrintCollectionCustomer(item, customers);
      return customer?.menu_show_ericdocs !== false;
    }),
    [collections, customers],
  );
  const filteredCollections = useMemo(
    () => shipmentCollections.filter((item) => String(item.shipment_date || "").slice(0, 10) === selectedCollectionDate),
    [shipmentCollections, selectedCollectionDate],
  );
  const selectedCollection = filteredCollections.find((item) => item.id === selectedCollectionId || item.shipment_id === selectedCollectionId) || null;
  const selectedTempPhytoFiles = selectedCollection?.documents?.temp_phyto_files || [];
  const selectedOriginalPhytoFiles = selectedCollection?.documents?.phyto_files || [];
  const selectedCheck = selectedCollection?.eric_docs_check || null;

  function openCollectionDetail(collectionId) {
    setSelectedCollectionId(collectionId);
    setDetailDrawerOpen(true);
  }

  function closeCollectionDetail() {
    setDetailDrawerOpen(false);
  }

  async function refreshState() {
    setLoading(true);
    setError("");
    try {
      const payload = await apiJson("/api/ukdocs/state");
      setState(payload.state);
    } catch (refreshError) {
      setError(refreshError.message);
    } finally {
      setLoading(false);
    }
  }

  async function uploadCollectionFile(kind, fileOrFiles) {
    if (!selectedCollection || !fileOrFiles) {
      return;
    }
    const files = Array.isArray(fileOrFiles)
      ? fileOrFiles
      : fileOrFiles instanceof FileList
        ? Array.from(fileOrFiles)
        : [fileOrFiles];
    if (!files.length) {
      return;
    }
    setSaving(true);
    setMessage("");
    setError("");
    try {
      let nextCollections = null;
      for (const file of files) {
        const contentBase64 = await fileToBase64(file);
        const payload = await apiJson(`/api/ukdocs-print/collections/${encodeURIComponent(selectedCollection.id)}/upload`, {
          method: "POST",
          body: JSON.stringify({
            kind,
            file: {
              file_name: file.name,
              mime_type: file.type || "application/octet-stream",
              content_base64: contentBase64,
            },
          }),
        });
        nextCollections = payload.print_collections || nextCollections;
      }
      if (nextCollections) {
        setState((current) => ({ ...current, print_collections: nextCollections || current?.print_collections || [] }));
      }
      setMessage(kind === "temp_phyto" ? "Temporary phyto PDF added." : kind === "phyto" ? "Original phytosanitary document added -- the papers go once everything is there." : "Inspection list saved.");
    } catch (uploadError) {
      setError(uploadError.message);
    } finally {
      setSaving(false);
    }
  }

  async function deleteCollectionDocument(kind, index = null) {
    if (!selectedCollection) {
      return;
    }
    if (!window.confirm("Delete this uploaded file?")) {
      return;
    }
    setSaving(true);
    setMessage("");
    setError("");
    try {
      const documentPath = index === null ? kind : `${kind}/${index}`;
      const payload = await apiJson(`/api/ukdocs-print/collections/${encodeURIComponent(selectedCollection.id)}/documents/${documentPath}`, {
        method: "DELETE",
      });
      setState((current) => ({ ...current, print_collections: payload.print_collections || current?.print_collections || [] }));
      setMessage("File deleted.");
    } catch (deleteError) {
      setError(deleteError.message);
    } finally {
      setSaving(false);
    }
  }

  async function runEricDocsCheck(collectionId) {
    setSaving(true);
    setMessage("");
    setError("");
    try {
      const payload = await apiJson(`/api/eric-docs/collections/${encodeURIComponent(collectionId)}/check`, { method: "POST" });
      setState((current) => ({ ...current, print_collections: payload.print_collections || current?.print_collections || [] }));
      setMessage(payload.collection?.eric_docs_check?.ok
        ? (payload.collection.eric_docs_check.match ? "Pieces match." : "Pieces MISMATCH -- see detail.")
        : (payload.collection?.eric_docs_check?.error || "Could not run the check."));
    } catch (checkError) {
      setError(checkError.message);
    } finally {
      setSaving(false);
    }
  }

  async function sendEricDocsPapers(collectionId) {
    setSaving(true);
    setMessage("");
    setError("");
    try {
      const payload = await apiJson(`/api/eric-docs/collections/${encodeURIComponent(collectionId)}/send`, { method: "POST" });
      setState((current) => ({ ...current, print_collections: payload.print_collections || current?.print_collections || [] }));
      if (payload.eric_docs_send_queued) {
        setMessage(`Queued -- add the missing docs in UKdocs Zendings: ${(payload.missing || []).join(", ")}. Papers will send automatically once ready.`);
      } else {
        setMessage(payload.eric_docs_email?.ok
          ? `Papers sent to ${payload.eric_docs_email.recipients.join(", ")}.`
          : (payload.eric_docs_email?.error || "Could not send Eric Docs papers."));
      }
    } catch (sendError) {
      setError(sendError.message);
    } finally {
      setSaving(false);
    }
  }

  return (
    <section className="overview-stack">
      {message && <div className="notice success">{message}</div>}
      {error && <div className="notice danger">{error}</div>}
      {loading && <div className="notice">Loading Eric Docs zendingen...</div>}

      <div className="ukdocs-collection-layout">
        <div className="data-table-card ukdocs-stack">
          <div className="section-header">
            <h2>Eric Docs zendingen</h2>
            <div className="row-actions spread-actions">
              <button type="button" onClick={refreshState} disabled={loading || saving}>Refresh</button>
            </div>
          </div>
          <div className="notice">Checks that the temporary phyto PDF's printed pieces total matches the inspection list's printed pieces total -- no XML needed. When PD Keuring's own "Pieces" field is filled in for the zending, that figure has to agree too. Once it passes, "Send papers" sends the same UKdocs Zendings papers to the Eric Docs mailbox configured in customer settings.</div>
          <div className="form-grid">
            <label className="wide">
              <span>Zending date</span>
              <input type="date" value={selectedCollectionDate} onChange={(event) => setSelectedCollectionDate(event.target.value)} />
            </label>
          </div>
          <div className="ukdocs-cards-grid">
            {filteredCollections.map((collection) => {
              const isActive = selectedCollection?.id === collection.id;
              const tileCheck = isActive ? selectedCheck : collection.eric_docs_check;
              const status = ericDocsCheckStatus(tileCheck);
              return (
                <div key={collection.id} className={`ukdocs-upload-card ukdocs-collection-tile${isActive ? " active" : ""}`}>
                  <strong>{collection.customer_name || collection.city_name || "Zending"}</strong>
                  <small>{collection.shipment_date || "-"}</small>
                  <small>City: {collection.city_name || "-"}</small>
                  <small>Invoices: {ukdocsCollectionInvoiceText(collection) || "No invoices linked yet"}</small>
                  <div className={`ukdocs-status-badge ${status.tone}`}>{status.label}</div>
                  <div className="row-actions spread-actions">
                    <button type="button" className="primary" onClick={() => openCollectionDetail(collection.id)}>{isActive ? "Opened" : "Open"}</button>
                    <button type="button" onClick={() => runEricDocsCheck(collection.id)} disabled={saving}>Check pieces</button>
                    <button
                      type="button"
                      onClick={() => sendEricDocsPapers(collection.id)}
                      disabled={saving || !tileCheck?.ok || tileCheck?.match !== true}
                      title={tileCheck?.ok && tileCheck?.match ? "Sends the same UKdocs Zendings papers to the Eric Docs mailbox" : "Run the pieces check successfully first"}
                    >
                      {collection.eric_docs_send_queue?.queued ? "Queued" : "Send papers"}
                    </button>
                  </div>
                </div>
              );
            })}
            {!filteredCollections.length && !loading && <div className="notice">No zendingen saved for {selectedCollectionDate}.</div>}
          </div>
        </div>

        {detailDrawerOpen && <button type="button" className="ukdocs-drawer-backdrop" onClick={closeCollectionDetail} aria-label="Close Eric Docs detail" />}
        <div className={`data-table-card ukdocs-stack ukdocs-drawer-panel${detailDrawerOpen ? " open" : ""}`}>
          <div className="section-header">
            <h2>Eric Docs detail</h2>
            {selectedCollection && <div className="row-actions"><button type="button" onClick={closeCollectionDetail}>Close</button></div>}
          </div>

          {!selectedCollection && <div className="notice">Open a zending to upload and check its documents.</div>}

          {selectedCollection && (
            <>
              <div className="form-grid">
                <label><span>Shipment reference</span><input value={selectedCollection.shipment_reference || ""} readOnly /></label>
                <label><span>Shipment date</span><input value={selectedCollection.shipment_date || ""} readOnly /></label>
                <label><span>Customer</span><input value={selectedCollection.customer_name || ""} readOnly /></label>
                <label><span>City</span><input value={selectedCollection.city_name || ""} readOnly /></label>
                <label><span>Expected pieces (PD Keuring)</span><input value={selectedCollection.expected_pieces || "Not filled in"} readOnly /></label>
              </div>

              <div className="ukdocs-upload-grid">
                <div className="ukdocs-upload-card">
                  <strong>Temporary phyto PDF</strong>
                  <input type="file" accept=".pdf" multiple onChange={(event) => uploadCollectionFile("temp_phyto", event.target.files)} disabled={saving} />
                  <small>{selectedTempPhytoFiles.length ? `${selectedTempPhytoFiles.length} temporary phyto PDF file(s) saved in Zending.` : "No file saved yet in Zending."}</small>
                  {!!selectedTempPhytoFiles.length && (
                    <div className="ukdocs-download-list">
                      {selectedTempPhytoFiles.map((file, index) => (
                        <div key={`${file.storage_name}-${index}`} className="row-actions spread-actions">
                          <a href={`/api/ukdocs-print/collections/${encodeURIComponent(selectedCollection.id)}/documents/temp_phyto/${index}`} target="_blank" rel="noreferrer" className="ukdocs-download-link">
                            {file.original_name || `Temporary phyto ${index + 1}`}
                          </a>
                          <button type="button" onClick={() => deleteCollectionDocument("temp_phyto", index)} disabled={saving}>Delete</button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
                <div className="ukdocs-upload-card">
                  <strong>Phytosanitaire document (original)</strong>
                  <input type="file" accept=".pdf,.xlsx,.xls" multiple onChange={(event) => uploadCollectionFile("phyto", event.target.files)} disabled={saving} />
                  <small>{selectedOriginalPhytoFiles.length ? `${selectedOriginalPhytoFiles.length} original phyto file(s) saved in Zending.` : "Comes after the inspection -- upload it here; the papers email goes once all papers are there."}</small>
                  {!!selectedOriginalPhytoFiles.length && (
                    <div className="ukdocs-download-list">
                      {selectedOriginalPhytoFiles.map((file, index) => (
                        <div key={`${file.storage_name}-${index}`} className="row-actions spread-actions">
                          <a href={`/api/ukdocs-print/collections/${encodeURIComponent(selectedCollection.id)}/documents/phyto/${index}`} target="_blank" rel="noreferrer" className="ukdocs-download-link">
                            {file.original_name || `Phyto ${index + 1}`}
                          </a>
                          <button type="button" onClick={() => deleteCollectionDocument("phyto", index)} disabled={saving}>Delete</button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
                <UkdocsInspectionListsCard
                  collection={selectedCollection}
                  saving={saving}
                  onUpload={(kind, file) => uploadCollectionFile(kind, file)}
                  onDelete={deleteCollectionDocument}
                />
              </div>

              <div className="row-actions spread-actions">
                <button type="button" className="primary" onClick={() => runEricDocsCheck(selectedCollection.id)} disabled={saving}>Check pieces</button>
                <button
                  type="button"
                  onClick={() => sendEricDocsPapers(selectedCollection.id)}
                  disabled={saving || !selectedCheck?.ok || selectedCheck?.match !== true}
                  title={selectedCheck?.ok && selectedCheck?.match ? "Sends the same UKdocs Zendings papers to the Eric Docs mailbox" : "Run the pieces check successfully first"}
                >
                  {selectedCollection.eric_docs_send_queue?.queued
                    ? "Queued"
                    : (selectedCollection.eric_docs_email?.ok ? "Resend papers" : "Send papers")}
                </button>
              </div>
              <div className={`ukdocs-status-badge ${ericDocsCheckStatus(selectedCheck).tone}`}>{ericDocsCheckStatus(selectedCheck).label}</div>
              {selectedCollection.eric_docs_send_queue?.queued && (
                <small>Queued -- will send automatically once all UKdocs Zendings papers are uploaded.</small>
              )}
              {selectedCheck?.checked_at && (
                <small>
                  Phyto total: {selectedCheck.phyto_total ?? "-"} -- Inspection total: {selectedCheck.inspection_total ?? "-"}
                  {selectedCheck.expected_pieces !== null && ` -- PD Keuring expected pieces: ${selectedCheck.expected_pieces}`}
                  {" "}-- Checked {formatTimestamp(selectedCheck.checked_at)}
                </small>
              )}
              {selectedCollection.eric_docs_email?.sent_at && (
                <small>
                  Papers {selectedCollection.eric_docs_email.ok ? "sent" : "not sent"} to {selectedCollection.eric_docs_email.recipients.join(", ") || "-"}
                  {selectedCollection.eric_docs_email.ok ? ` at ${formatTimestamp(selectedCollection.eric_docs_email.sent_at)}` : `: ${selectedCollection.eric_docs_email.error}`}
                </small>
              )}
            </>
          )}
        </div>
      </div>
    </section>
  );
}

// "Go to step" hands the target menu the shipment's date (and zending) via
// sessionStorage; the menu picks it up when it opens. Short-lived, so it
// never surprises someone opening that menu later by hand.
const PD_STEP_PLAN_FOCUS_KEY = "pd-step-plan-focus";

// A page can refuse to be left (PD Keuring when the step plan's fields are
// still missing); the app shell asks it before switching pages.
let pageLeaveGuard = null;

function setPageLeaveGuard(guard) {
  pageLeaveGuard = guard;
}

// The labels of the PD Keuring row fields the plan can ask for.
const PD_STEP_PLAN_FIELD_LABELS = {
  reference_connect: "Connect number",
  truck_number: "Truck number",
  trailer_number: "Licence plate",
  expected_pieces: "Pieces",
};

function setPdStepPlanFocus(page, date, collectionId, action = "", fields = []) {
  try {
    sessionStorage.setItem("pd-step-plan-date", date);
    sessionStorage.setItem(PD_STEP_PLAN_FOCUS_KEY, JSON.stringify({ page, date, collection_id: collectionId, action, fields, at: Date.now() }));
  } catch {
    // Storage blocked: the menu just opens on today.
  }
}

function pdStepPlanFocus(page) {
  try {
    const focus = JSON.parse(sessionStorage.getItem(PD_STEP_PLAN_FOCUS_KEY) || "null");
    return focus && focus.page === page && Date.now() - Number(focus.at || 0) < 30000 ? focus : null;
  } catch {
    return null;
  }
}

const PD_STEP_PLAN_PAGE_LABELS = {
  pdkeuring: "PD Keuring",
  ukdocs: "UKDocs Export",
  ukdocscsi: "UKDocs CSI",
  ericdocs: "Eric Docs",
};

function PdStepPlanPage({ onNavigate }) {
  const [date, setDate] = useState(() => {
    try {
      return sessionStorage.getItem("pd-step-plan-date") || localDateIso();
    } catch {
      return localDateIso();
    }
  });
  // A step plan task opened from the widget: its own day.
  useEffect(() => {
    const apply = (link) => {
      if (link?.page === "pdstepplan" && /^\d{4}-\d{2}-\d{2}$/.test(String(link.date || ""))) {
        setDate(link.date);
        window.__appOpenLink = null;
      }
    };
    apply(window.__appOpenLink);
    const onLink = (event) => apply(event.detail);
    window.addEventListener("app-open-link", onLink);
    return () => window.removeEventListener("app-open-link", onLink);
  }, []);
  const [plan, setPlan] = useState(null);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState("");
  // Right-click / "Continue without..." menu: { row, step, x, y }.
  const [skipMenu, setSkipMenu] = useState(null);

  useEffect(() => {
    if (!skipMenu) return undefined;
    const close = () => setSkipMenu(null);
    window.addEventListener("click", close);
    window.addEventListener("scroll", close, true);
    return () => {
      window.removeEventListener("click", close);
      window.removeEventListener("scroll", close, true);
    };
  }, [skipMenu]);

  function load() {
    return apiJson(`/api/pd-step-plan?date=${encodeURIComponent(date)}`)
      .then((payload) => { setPlan(payload); setError(""); })
      .catch((loadError) => setError(loadError.message))
      .finally(() => setLoading(false));
  }

  useEffect(() => {
    setLoading(true);
    load();
    const timer = setInterval(load, 30000);
    return () => clearInterval(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [date]);

  function goTo(row, step) {
    // The missing row fields go along, so PD Keuring can highlight them.
    setPdStepPlanFocus(step.page, date, row.collection_id, "", (step.skippable || []).map((item) => item.code));
    onNavigate(step.page);
  }

  // Step 1 starts here. Nothing set up for the date yet: PD Keuring opens
  // on its proposals (last week's same weekday, accept in one go); already
  // some shipments: straight to the new-row form for one more.
  function createPdKeuring() {
    setPdStepPlanFocus("pdkeuring", date, "", plan?.rows?.length ? "create" : "");
    onNavigate("pdkeuring");
  }

  // "Continue without ..." (skip = true) or undo it, for one or more items.
  async function setSkipped(row, items, skip) {
    setSkipMenu(null);
    const names = items.map((item) => item.label).join(", ");
    if (skip && !window.confirm(
      `${row.customer_name}${row.city_name ? ` (${row.city_name})` : ""}\n\n`
      + `Continue without: ${names}?\n\nOnly do this when it really isn't there for this shipment. It stays visible as a warning.`,
    )) {
      return;
    }
    setBusy(true);
    try {
      setPlan(await apiJson("/api/pd-step-plan/skip", {
        method: "POST",
        body: JSON.stringify({ collection_id: row.collection_id, codes: items.map((item) => item.code), skip }),
      }));
    } catch (saveError) {
      setError(saveError.message);
    } finally {
      setBusy(false);
    }
  }

  // A step done in another program (Uniware, e-Cert): mark it (or undo).
  async function markStep(step, row, done, notNeeded = false) {
    const what = `${row ? `${row.customer_name} -- ` : ""}${step.number ? `${step.number}. ` : ""}${step.label}`;
    if (done && !window.confirm(`${what}${String.fromCharCode(10, 10)}${notNeeded ? "Mark as not needed" : "Mark as done"}?`)) {
      return;
    }
    setBusy(true);
    try {
      setPlan(await apiJson("/api/pd-step-plan/mark", {
        method: "POST",
        body: JSON.stringify({ date, step: step.key, collection_id: row?.collection_id || "", done, not_needed: notNeeded }),
      }));
      setError("");
    } catch (saveError) {
      setError(saveError.message);
    } finally {
      setBusy(false);
    }
  }

  function showDaySteps() {
    document.getElementById("pd-day-steps")?.scrollIntoView({ behavior: "smooth", block: "start" });
  }

  function openSkipMenu(event, row, step) {
    if (!step?.skippable?.length) return;
    event.preventDefault();
    event.stopPropagation();
    const rect = event.currentTarget.getBoundingClientRect();
    const x = event.type === "contextmenu" ? event.clientX : rect.left;
    const y = event.type === "contextmenu" ? event.clientY : rect.bottom + 4;
    setSkipMenu({ row, step, x, y });
  }

  const rows = plan?.rows || [];
  const summary = plan?.summary;
  const day = plan?.day;
  const stepTitles = ["1. PD Keuring", "2-9. Day steps", "10. Connect / truck / plate (/ pieces)", "11. Tour data dumps + IPAFFS", "12. Invoices & export docs", "13. CSI / Eric Docs", "14. e-Cert finish + signature"];
  const markInfo = (mark) => (mark ? `${mark.not_needed ? "not needed" : "done"} by ${mark.by || "?"}${mark.at ? `, ${formatTimestamp(mark.at)}` : ""}` : "");

  return (
    <section className="overview-stack">
      <div className="row-actions spread-actions">
        <label>
          <span>Shipment date</span>
          <input type="date" value={date} onChange={(event) => setDate(event.target.value)} />
        </label>
        <button type="button" onClick={() => { setLoading(true); load(); }} disabled={loading}>Refresh</button>
      </div>

      <div className="notice">
        The whole day in order. <strong>1</strong> set up the PD keuringen (the stock control too);{" "}
        <strong>2-9</strong> the day steps, once per day: phyto inspection docs, tours in Connect, the BQ order, stock control finished,
        phyto shipments and e-Cert; then per shipment <strong>10</strong> connect number, truck and licence plate,{" "}
        <strong>11</strong> the tour data dumps and IPAFFS, <strong>12</strong> invoices and export documents, <strong>13</strong> the papers through
        UKDocs CSI (export) or Eric Docs (nakeuring) and <strong>14</strong> finish it in e-Cert with the digital signature.
        A step opens when the one before it is done; <strong>Go to</strong> opens the menu for that step, <strong>Mark done</strong> is for a step
        done in another program (Uniware, e-Cert).
      </div>
      {error && <div className="notice danger">{error}</div>}

      <div className="data-table-card">
        <div className="row-actions spread-actions">
          <div>
            <strong>Step 1 -- PD keuringen for {date}</strong>
            <div className="muted">
              {rows.length
                ? `${rows.length} shipment(s) set up. Add another one for a shipment that still needs papers.`
                : "No shipments set up yet for this date. Start here: PD Keuring opens with last week's shipments of the same weekday as proposals -- accept them in one go, or add rows by hand."}
            </div>
          </div>
          <button type="button" className="primary" onClick={createPdKeuring}>
            {rows.length ? `+ Add a PD keuring for ${date}` : `+ Set up PD keuringen for ${date}`}
          </button>
        </div>
      </div>

      {day && (
        <div className="data-table-card" id="pd-day-steps">
          <div className="row-actions spread-actions">
            <div>
              <strong>Day steps 1-9 -- once for {date}</strong>
              <div className="muted">
                {day.stock_name ? `Kept on the stock control row (${day.stock_name}).` : "Start with the stock control (Voorraad) PD keuring -- the day steps are kept on it."}
                {" "}The shipments' step 10 opens when these are done.
              </div>
            </div>
            <span className={`ukdocs-status-badge ${day.complete ? "success" : "info"}`}>
              {day.complete ? "✓ Day steps done" : `Step ${day.steps[day.current_step].number} of 9`}
            </span>
          </div>
          <div className="table-wrap">
            <table className="data-table">
              <tbody>
                {day.steps.map((step, index) => {
                  const state = step.done ? "done" : index === day.current_step ? "current" : "locked";
                  return (
                    <tr key={step.key} style={{ background: state === "done" ? "var(--x-ecfdf5)" : state === "current" ? "var(--x-fffbeb)" : undefined }}>
                      <td style={{ width: 40, fontWeight: 700 }}>{step.number}.</td>
                      <td>
                        <div style={{ fontWeight: 600, color: state === "done" ? "var(--x-15803d)" : state === "current" ? "var(--x-b45309)" : "var(--x-9ca3af)" }}>
                          {state === "done" ? "✓ " : state === "current" ? "▶ " : "🔒 "}{step.label}
                        </div>
                        {state === "current" && step.missing.map((item) => <div key={item} className="muted">• {item}</div>)}
                        {step.mark && <div className="muted">{markInfo(step.mark)}</div>}
                        {step.auto_done && !step.mark && <div className="muted">complete in Phyto Inspection</div>}
                      </td>
                      <td style={{ width: 260 }}>
                        {state === "current" && !step.manual && (
                          <button type="button" className="primary" onClick={createPdKeuring}>Go to PD Keuring</button>
                        )}
                        {state === "current" && step.page === "ukdocsinspection" && (
                          <button type="button" className="primary" onClick={() => { setPdStepPlanFocus(step.page, date, day.collection_id); onNavigate(step.page); }}>
                            Go to Phyto Inspection
                          </button>
                        )}
                        {state === "current" && step.manual && (
                          <button type="button" className={step.page ? "" : "primary"} onClick={() => markStep(step, null, true)} disabled={busy}>Mark done</button>
                        )}
                        {step.done && step.manual && step.mark && (
                          <button type="button" className="link-button" onClick={() => markStep(step, null, false)} disabled={busy}>undo</button>
                        )}
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        </div>
      )}

      {summary && (
        <div className="row-actions">
          {stepTitles.map((title, index) => (
            <span key={title} className={`ukdocs-status-badge ${summary.at_step[index] ? "info" : "muted"}`}>{title}: {summary.at_step[index]}</span>
          ))}
          <span className={`ukdocs-status-badge ${summary.complete ? "success" : "muted"}`}>Complete: {summary.complete} / {summary.total}</span>
        </div>
      )}

      <div className="data-table-card">
        <div className="table-wrap">
          <table className="data-table">
            <thead>
              <tr>
                <th>Shipment</th>
                {stepTitles.map((title) => <th key={title}>{title}</th>)}
                <th>Next</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((row) => {
                const current = row.steps[row.current_step];
                return (
                  <tr key={row.collection_id}>
                    <td>
                      <strong>{row.customer_name}</strong>
                      <div className="muted">{[row.city_name, row.pd_type].filter(Boolean).join(" · ") || "-"}</div>
                      {row.shipment_reference && <div className="muted">Invoices {row.shipment_reference}</div>}
                    </td>
                    {row.steps.map((step, index) => {
                      const state = step.done ? "done" : index === row.current_step ? "current" : "locked";
                      return (
                        <td
                          key={step.key}
                          style={{ background: state === "done" ? "var(--x-ecfdf5)" : state === "current" ? "var(--x-fffbeb)" : undefined }}
                          onContextMenu={state === "current" ? (event) => openSkipMenu(event, row, step) : undefined}
                          title={state === "current" && step.skippable?.length ? "Right-click to continue without a missing item" : undefined}
                        >
                          <div style={{ fontWeight: 600, color: state === "done" ? "var(--x-15803d)" : state === "current" ? "var(--x-b45309)" : "var(--x-9ca3af)" }}>
                            {state === "done" ? "✓ " : state === "current" ? "▶ " : "🔒 "}{step.label}
                          </div>
                          {state === "current" && step.missing.map((item) => <div key={item} className="muted">• {item}</div>)}
                          {state === "current" && step.status && <div className="muted">{step.status}</div>}
                          {step.mark && <div className="muted">{markInfo(step.mark)}</div>}
                          {step.done && step.manual && step.mark && (
                            <button type="button" className="link-button" onClick={() => markStep(step, row, false)} disabled={busy}>undo</button>
                          )}
                          {(step.skipped || []).map((item) => (
                            <div key={item.code} style={{ color: "var(--x-b45309)" }}>
                              ⚠ Without {item.label} <span className="muted">({item.by})</span>{" "}
                              <button type="button" className="link-button" onClick={() => setSkipped(row, [item], false)} disabled={busy}>undo</button>
                            </div>
                          ))}
                        </td>
                      );
                    })}
                    <td>
                      {row.complete
                        ? <span className="ukdocs-status-badge success">✓ Complete</span>
                        : (
                          <div className="row-actions">
                            {current.day ? (
                              <button type="button" className="primary" onClick={showDaySteps}>See the day steps</button>
                            ) : current.manual ? (
                              <>
                                <button type="button" className="primary" onClick={() => markStep(current, row, true)} disabled={busy}>Mark done</button>
                                {current.key === "tour_dumps" && (
                                  <button type="button" onClick={() => markStep(current, row, true, true)} disabled={busy}>Not needed</button>
                                )}
                              </>
                            ) : (
                              <button type="button" className="primary" onClick={() => goTo(row, current)}>
                                Go to {PD_STEP_PLAN_PAGE_LABELS[current.page] || current.page}
                              </button>
                            )}
                            {!!current.skippable?.length && (
                              <button type="button" onClick={(event) => openSkipMenu(event, row, current)} disabled={busy} title="Continue this step without a missing item">
                                Continue without…
                              </button>
                            )}
                          </div>
                        )}
                    </td>
                  </tr>
                );
              })}
              {!rows.length && !loading && (
                <tr>
                  <td colSpan={stepTitles.length + 2}>
                    No export shipments for {date} yet.
{" "}
                    <button type="button" className="primary" onClick={createPdKeuring}>+ Set up PD keuringen</button>
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {skipMenu && (
        <div
          role="menu"
          onClick={(event) => event.stopPropagation()}
          style={{
            position: "fixed", left: Math.min(skipMenu.x, window.innerWidth - 280), top: Math.min(skipMenu.y, window.innerHeight - 180),
            zIndex: 1000, background: "var(--x-ffffff)", border: "1px solid var(--x-b8c2cc)", borderRadius: 8, boxShadow: "0 6px 18px rgba(0,0,0,.15)",
            padding: 6, minWidth: 240,
          }}
        >
          <div className="muted" style={{ padding: "4px 8px" }}>{skipMenu.row.customer_name} -- {skipMenu.step.label}</div>
          {skipMenu.step.skippable.map((item) => (
            <button key={item.code} type="button" className="link-button" style={{ display: "block", padding: "6px 8px", textAlign: "left", width: "100%" }} onClick={() => setSkipped(skipMenu.row, [item], true)}>
              Continue without {item.label}
            </button>
          ))}
          {skipMenu.step.skippable.length > 1 && (
            <button type="button" className="link-button" style={{ display: "block", padding: "6px 8px", textAlign: "left", width: "100%", fontWeight: 600 }} onClick={() => setSkipped(skipMenu.row, skipMenu.step.skippable, true)}>
              Continue without all of these
            </button>
          )}
        </div>
      )}
    </section>
  );
}

// A text box with a real dropdown of every value used before: opened (click,
// focus or the ▾), it lists ALL of them -- not only the ones that match
// what is in the box, as the browser's own suggestion list does -- most used
// first; typing narrows the list, and a new value can still be typed.
function UsedValuesCombo({ value, onChange, options, placeholder = "", ariaLabel = "", className = "" }) {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState(null);
  const [active, setActive] = useState(-1);
  const inputRef = useRef(null);
  const listRef = useRef(null);
  const current = String(value || "");
  const words = String(query || "").toLowerCase().split(/\s+/).filter(Boolean);
  const shown = query === null ? options : options.filter((option) => words.every((word) => option.value.toLowerCase().includes(word)));
  const openAll = () => {
    setQuery(null);
    setOpen(true);
    setActive(Math.max(0, options.findIndex((option) => option.value === current)));
  };
  const pick = (next) => {
    onChange(next);
    setOpen(false);
    setQuery(null);
  };
  useEffect(() => {
    if (!open || active < 0) return;
    listRef.current?.querySelector(`[data-index="${active}"]`)?.scrollIntoView({ block: "nearest" });
  }, [open, active]);
  return (
    <span className={`used-combo${open ? " open" : ""}`}>
      <input
        ref={inputRef}
        className={className}
        value={current}
        placeholder={placeholder}
        aria-label={ariaLabel || undefined}
        role="combobox"
        aria-expanded={open}
        autoComplete="off"
        onFocus={openAll}
        onClick={() => { if (!open) openAll(); }}
        onBlur={() => window.setTimeout(() => setOpen(false), 120)}
        onChange={(event) => { onChange(event.target.value); setQuery(event.target.value); setOpen(true); setActive(0); }}
        onKeyDown={(event) => {
          if (event.key === "ArrowDown") { event.preventDefault(); if (!open) openAll(); else setActive((index) => Math.min(shown.length - 1, index + 1)); }
          else if (event.key === "ArrowUp") { event.preventDefault(); setActive((index) => Math.max(0, index - 1)); }
          else if (event.key === "Enter" && open && shown[active]) { event.preventDefault(); pick(shown[active].value); }
          else if (event.key === "Escape") setOpen(false);
        }}
      />
      <button type="button" className="used-combo-toggle" tabIndex={-1} aria-label="Show all values"
        onMouseDown={(event) => event.preventDefault()}
        onClick={() => { if (open) setOpen(false); else { openAll(); inputRef.current?.focus(); } }}>▾</button>
      {open && (
        <ul className="used-combo-list" role="listbox" ref={listRef}>
          {shown.map((option, index) => (
            <li key={option.value} data-index={index} role="option" aria-selected={option.value === current}
              className={`${index === active ? "active" : ""}${option.value === current ? " chosen" : ""}`}
              onMouseDown={(event) => { event.preventDefault(); pick(option.value); }}
              onMouseEnter={() => setActive(index)}>
              <span>{option.value === current && <b className="used-combo-check">✓ </b>}{option.value}</span>
              {option.count > 0 && <small>{option.count}×</small>}
            </li>
          ))}
          {!shown.length && <li className="used-combo-empty">New value -- not used before</li>}
        </ul>
      )}
    </span>
  );
}

// Every value a field has had (all shipments so far) plus the synced
// dropdown list, the most used first; the same text in other capitals is
// one option (its most used spelling).
function buildUsedValueOptions(rows, field, extra = []) {
  const byKey = new Map();
  const add = (raw, count) => {
    const text = String(raw ?? "").trim();
    if (!text) return;
    const key = text.toLowerCase();
    const entry = byKey.get(key) || { count: 0, spellings: new Map() };
    entry.count += count;
    entry.spellings.set(text, (entry.spellings.get(text) || 0) + count + 0.001);
    byKey.set(key, entry);
  };
  for (const row of rows) add(row?.[field], 1);
  for (const value of extra || []) add(value, 0);
  return [...byKey.values()]
    .map((entry) => ({ value: [...entry.spellings.entries()].sort((left, right) => right[1] - left[1])[0][0], count: entry.count }))
    .sort((left, right) => right.count - left.count || left.value.localeCompare(right.value));
}

// The inspection list card: the first list (what makes the shipment
// complete) plus any more for the same shipment -- each its own Open /
// Delete; "add" picks one or several files (the first becomes the main one
// when there is none yet).
// What the Uniware recorder's daily factuur fetch did (newest first): how
// many facturen the day needed, fetched and matched, and which are still
// missing -- not found in Uniware, or a PDF that didn't match.
function FinanceAuditFetchSummary({ runs, isAdmin, invoiceDocuments = [] }) {
  // The last run, without what has its factuur by now (fetched later in
  // the day, or a wrong PDF whose right one came in since).
  const have = new Set((invoiceDocuments || []).map((document) => String(document.invoice_number || "").trim()).filter(Boolean));
  const fileNumber = (name) => (String(name || "").match(/\d{5,}/) || [""])[0];
  const last = runs[0] ? {
    ...runs[0],
    not_found: (runs[0].not_found || []).filter((number) => !have.has(String(number))),
    not_matched: (runs[0].not_matched || []).filter((item) => !have.has(String(item.invoice || "")) && !have.has(fileNumber(item.file))),
    still_needed: (runs[0].still_needed || []).filter((number) => !have.has(String(number))),
  } : null;
  // "Check what the next fetch gets": the open audits without a factuur.
  const [check, setCheck] = useState(null);
  const [checking, setChecking] = useState(false);
  // "Run on this PC": the recorder action, started from here too (only
  // looked for once opened -- PCs without the recorder aren't asked).
  const [showRun, setShowRun] = useState(false);
  async function runCheck() {
    setChecking(true);
    try {
      setCheck(await apiJson("/api/finance-audit/needed-invoices"));
    } catch (checkError) {
      setCheck({ error: checkError.message });
    } finally {
      setChecking(false);
    }
  }
  const checkRows = check && !check.error ? [
    ...(check.items || []).flatMap((item) => item.invoice_numbers.map((number) => ({ ...item, number, status: "fetch" }))),
    ...(check.missing_ref || []).flatMap((item) => item.invoice_numbers.map((number) => ({ ...item, number, status: "no_code" }))),
    ...(check.no_number || []).map((item) => ({ ...item, number: "", ref: "", status: "no_number" })),
  ].sort((left, right) => String(left.date).localeCompare(String(right.date)) || String(left.customer).localeCompare(String(right.customer))) : [];
  const categoryLabel = (code) => UKDOCS_CATEGORY_DEFINITIONS.find((item) => item.code === code)?.label || code;
  const line = (run) => {
    const missing = run.still_needed?.length || 0;
    return `${run.date}: ${run.needed} to fetch, ${run.sent} fetched, ${run.matched.length} matched${missing ? `, ${missing} still missing (last 60 days)` : " -- complete"}`;
  };
  return (
    <div className={`fa-fetch${last && !(last.still_needed || []).length ? " ok" : ""}`}>
      <div className="fa-fetch-head">
        <strong>Automatic factuur fetch (Uniware)</strong>
        <span>{last ? `${line(last)} · ${formatTimestamp(last.at)}${last.agent ? ` · ${last.agent}` : ""}` : "Not run yet -- the recorder's daily action fills this in."}</span>
        <button type="button" className="fa-fetch-check" onClick={check ? () => setCheck(null) : runCheck} disabled={checking}>{checking ? "Checking…" : check ? "Hide the check" : "Check what the next fetch gets"}</button>
        <button type="button" className="fa-fetch-check" onClick={() => setShowRun((value) => !value)} aria-expanded={showRun}>{showRun ? "Hide" : "▶ Fetch now (this PC)"}</button>
        {isAdmin && <a href="/api/agent/recorder-config" title="The recorder's connection file (server address + key) -- put it in the uniware-recorder folder">Recorder setup file</a>}
      </div>
      {showRun && <div className="tw-admin fa-fetch-run"><TwRecorderRun action="facturen-finance-audit" /></div>}
      {check?.error && <div className="notice danger">{check.error}</div>}
      {check && !check.error && (
        <div className="fa-fetch-checklist">
          <div>
            Open audits without a factuur, {check.from} -- {check.to}:{" "}
            <strong>{checkRows.filter((row) => row.status === "fetch").length} will be fetched</strong>
            {checkRows.some((row) => row.status === "no_code") && <>, <span className="ukdocs-status-badge danger">{checkRows.filter((row) => row.status === "no_code").length} no customer code</span></>}
            {checkRows.some((row) => row.status === "no_number") && <>, <span className="ukdocs-status-badge danger">{checkRows.filter((row) => row.status === "no_number").length} no factuur number</span></>}
          </div>
          {!!check.duplicates?.length && (
            <div className="fa-fetch-line">
              <span className="ukdocs-status-badge danger">Same factuur number on more than one sending</span>
              {check.duplicates.map((item) => (
                <span key={item.invoice} title="One of these is wrong -- fix it with right-click > Edit invoice numbers on that sending">
                  <strong>{item.invoice}</strong>: {item.sendings.map((owner) => `${owner.customer || "?"} ${owner.date} (${categoryLabel(owner.category)})`).join(" + ")};
                </span>
              ))}
            </div>
          )}
          {checkRows.length ? (
            <div className="table-wrap">
              <table className="data-table">
                <thead><tr><th>Datum</th><th>Customer</th><th>Type</th><th>Factuur nummer</th><th>Uniware code</th><th>Next fetch</th></tr></thead>
                <tbody>
                  {checkRows.map((row, index) => (
                    <tr key={`${row.shipment_id}-${row.category}-${row.number}-${index}`}>
                      <td>{row.date}</td>
                      <td>{row.customer || "-"}</td>
                      <td>{categoryLabel(row.category)}</td>
                      <td>{row.number || "-"}</td>
                      <td>{row.ref || "-"}</td>
                      <td>
                        {row.status === "fetch" && <span className="ukdocs-status-badge success">✓ will be fetched</span>}
                        {row.status === "no_code" && <span className="ukdocs-status-badge danger">✕ no Uniware code -- set it on the customer</span>}
                        {row.status === "no_number" && <span className="ukdocs-status-badge danger">✕ no factuur number on the sending</span>}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          ) : <div className="muted">Nothing open -- every audit of the last 60 days has its factuur.</div>}
        </div>
      )}
      {!!last?.not_found?.length && <div className="fa-fetch-line"><span className="ukdocs-status-badge danger">Not found in Uniware</span> {last.not_found.join(", ")}</div>}
      {!!last?.not_matched?.length && (
        <div className="fa-fetch-line">
          <span className="ukdocs-status-badge danger">Fetched, not matched</span>
          {last.not_matched.map((item, index) => <span key={index} title={item.error}>{item.invoice || item.file}{index < last.not_matched.length - 1 ? ", " : ""}</span>)}
        </div>
      )}
      {!!last?.still_needed?.length && <div className="fa-fetch-line"><span className="ukdocs-status-badge muted">Still without factuur</span> {last.still_needed.join(", ")}</div>}
      {!!last?.missing_ref?.length && <div className="fa-fetch-line"><span className="ukdocs-status-badge danger">No Uniware ref yet (can't be fetched)</span> {last.missing_ref.join(", ")} <small>-- set the customer's "Uniware factuur code" (UKDocs Export &gt; Customers &gt; Finance Audit)</small></div>}
      {runs.length > 1 && (
        <details className="fa-fetch-more">
          <summary>Earlier fetches ({runs.length - 1})</summary>
          <ul>{runs.slice(1, 15).map((run, index) => <li key={index}>{line(run)} · {formatTimestamp(run.at)}{run.not_found?.length ? ` · not found: ${run.not_found.join(", ")}` : ""}</li>)}</ul>
        </details>
      )}
    </div>
  );
}

function UkdocsInspectionListsCard({ collection, saving, onUpload, onDelete, title = "Inspection list", accept = ".pdf" }) {
  const first = collection?.documents?.inspection_list?.storage_name ? collection.documents.inspection_list : null;
  const extra = (collection?.documents?.inspection_list_extra_files || []).filter((document) => document?.storage_name);
  const all = [
    ...(first ? [{ document: first, kind: "inspection_list", index: null, href: "inspection_list" }] : []),
    ...extra.map((document, index) => ({ document, kind: "inspection_list_extra", index, href: `inspection_list_extra/${index}` })),
  ];
  const collectionId = encodeURIComponent(collection?.id || "");
  return (
    <div className="ukdocs-upload-card">
      <strong>{title}{all.length > 1 ? ` (${all.length})` : ""}</strong>
      <input
        type="file"
        accept={accept}
        multiple
        onChange={async (event) => {
          const chosen = Array.from(event.target.files || []);
          event.target.value = "";
          let hasFirst = Boolean(first);
          for (const nextFile of chosen) {
            await onUpload(hasFirst ? "inspection_list_extra" : "inspection_list", nextFile);
            hasFirst = true;
          }
        }}
        disabled={saving}
      />
      <small>{all.length ? (all.length === 1 ? "1 inspection list saved -- choose a file to add a second one." : `${all.length} inspection lists saved (one is enough to be complete).`) : "No file saved yet. Several lists for one shipment are fine."}</small>
      {all.map((item, position) => (
        <div key={`${item.document.storage_name}-${position}`} className="row-actions spread-actions">
          <a href={`/api/ukdocs-print/collections/${collectionId}/documents/${item.href}`} target="_blank" rel="noreferrer" className="ukdocs-download-link">
            {item.document.original_name || `Inspection list ${position + 1}`}
          </a>
          {item.document.saved_at && <small>{formatTimestamp(item.document.saved_at)}</small>}
          <button type="button" onClick={() => onDelete(item.kind, item.index)} disabled={saving}>Delete</button>
        </div>
      ))}
    </div>
  );
}

function PdKeuringPage({ currentUser }) {
  const canManageSettings = hasPermission(currentUser, PERMISSIONS.SETTINGS_MANAGE);
  const [activeMenu, setActiveMenu] = useState("planning");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");
  const [state, setState] = useState(null);
  const [referenceDraft, setReferenceDraft] = useState(emptyUkdocsPdReferenceEntry());
  const [backfillIncludeOud, setBackfillIncludeOud] = useState(false);
  const [backfillBusy, setBackfillBusy] = useState(false);
  const [buildingReferenceFromHistory, setBuildingReferenceFromHistory] = useState(false);
  const [backfillResult, setBackfillResult] = useState(null);
  const [selectedDate, setSelectedDate] = useState(() => pdStepPlanFocus("pdkeuring")?.date || localDateIso());
  // Opened from the PD Step Plan's "Create PD keuring": the new-row form is
  // already open for that date.
  const [rowDraft, setRowDraft] = useState(() => (pdStepPlanFocus("pdkeuring")?.action === "create" ? emptyRowDraft() : null));
  // Set when a new row would land on the same shipment key as an existing
  // row of the day -- the user picks join or separate before it's saved.
  const [duplicateMatch, setDuplicateMatch] = useState(null);
  const [proposalSelectedIds, setProposalSelectedIds] = useState([]);
  // Uncommitted inline edits, keyed by row id -- only reference_connect,
  // expected_boxes, and expected_pieces are ever edited this way (fast,
  // no need to open the row form). Everything else stays edit-only.
  const [inlineEdits, setInlineEdits] = useState({});

  useEffect(() => {
    let cancelled = false;
    apiJson("/api/ukdocs/state")
      .then((payload) => {
        if (!cancelled) {
          setState(payload.state);
        }
      })
      .catch((loadError) => {
        if (!cancelled) {
          setError(loadError.message);
        }
      })
      .finally(() => {
        if (!cancelled) {
          setLoading(false);
        }
      });
    return () => {
      cancelled = true;
    };
  }, [currentUser]);

  const pdReference = state?.pd_reference || [];
  const pdDropdownOptions = state?.pd_dropdown_options || {};
  const printCollections = state?.print_collections || [];
  const customers = state?.customers || [];
  const dayRows = printCollections.filter((item) => String(item.shipment_date || "").slice(0, 10) === selectedDate);
  // The form's dropdowns: every value used until today (all shipments) plus
  // the synced lists -- not for truck, trailer, boxes, pieces.
  const usedOptions = useMemo(() => ({
    city_name: buildUsedValueOptions(printCollections, "city_name", pdDropdownOptions.cities),
    border_crossing: buildUsedValueOptions(printCollections, "border_crossing"),
    hub_code: buildUsedValueOptions(printCollections, "hub_code", pdDropdownOptions.hub_codes),
    remark: buildUsedValueOptions(printCollections, "remark"),
    pd_form: buildUsedValueOptions(printCollections, "pd_form", pdDropdownOptions.pd_form_letters),
    re_export: buildUsedValueOptions(printCollections, "re_export"),
    pd_type: buildUsedValueOptions(printCollections, "pd_type", pdDropdownOptions.types),
    pd_code: buildUsedValueOptions(printCollections, "pd_code", pdDropdownOptions.pd_codes),
    pd_keuring_made_by: buildUsedValueOptions(printCollections, "pd_keuring_made_by", pdDropdownOptions.staff_names),
  }), [printCollections, pdDropdownOptions]);
  // Opened from the PD Step Plan for one shipment: the fields it still
  // needs glow until they're filled in, and leaving with some still empty
  // asks to continue without them (recorded in the plan).
  const [stepFocus] = useState(() => pdStepPlanFocus("pdkeuring"));
  const stepFocusRowId = stepFocus?.collection_id || "";
  const stepNeededFields = (stepFocus?.fields || []).filter((field) => PD_STEP_PLAN_FIELD_LABELS[field]);
  const stepNeeded = (row, field) => row.id === stepFocusRowId && stepNeededFields.includes(field) && !String(inlineFieldValue(row, field) || "").trim();
  const stepLeaveCheck = useRef(null);
  stepLeaveCheck.current = () => {
    const row = dayRows.find((item) => item.id === stepFocusRowId) || printCollections.find((item) => item.id === stepFocusRowId);
    if (!row || !stepNeededFields.length) return true;
    if (isRowDirty(row) && !window.confirm(`${row.customer_name || row.city_name || "This shipment"}: you have changes that aren't saved yet (press Save first).\n\nLeave without saving them?`)) {
      return false;
    }
    const missing = stepNeededFields.filter((field) => !String(row[field] || "").trim());
    if (!missing.length) return true;
    const labels = missing.map((field) => PD_STEP_PLAN_FIELD_LABELS[field]).join(", ");
    if (!window.confirm(`${row.customer_name || row.city_name || "This shipment"}: still missing ${labels}.\n\nOK = continue without them (shown as a warning in the PD Step Plan)\nCancel = stay and fill them in`)) {
      return false;
    }
    apiJson("/api/pd-step-plan/skip", { method: "POST", body: JSON.stringify({ collection_id: row.id, codes: missing, skip: true }) }).catch(() => {});
    return true;
  };
  useEffect(() => {
    if (!stepFocusRowId || !stepNeededFields.length) return undefined;
    setPageLeaveGuard(() => stepLeaveCheck.current());
    return () => setPageLeaveGuard(null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stepFocusRowId]);
  useEffect(() => {
    if (!stepFocusRowId) return;
    const element = document.getElementById(`pd-row-${stepFocusRowId}`);
    if (element) element.scrollIntoView({ block: "center", behavior: "smooth" });
  }, [stepFocusRowId, dayRows.length]);
  const lastWeekDate = addDaysToIso(selectedDate, -7);
  const lastWeekRows = printCollections.filter((item) => String(item.shipment_date || "").slice(0, 10) === lastWeekDate);
  const showProposals = dayRows.length === 0 && lastWeekRows.length > 0;

  useEffect(() => {
    // Same-weekday-last-week rows are proposed checked by default -- the
    // recurring route usually still runs; staff uncheck what doesn't apply.
    setProposalSelectedIds(dayRows.length === 0 ? lastWeekRows.map((item) => item.id) : []);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selectedDate, state]);

  function toggleProposalSelected(rowId) {
    setProposalSelectedIds((current) => (current.includes(rowId) ? current.filter((id) => id !== rowId) : [...current, rowId]));
  }

  async function acceptProposals() {
    const accepted = lastWeekRows.filter((item) => proposalSelectedIds.includes(item.id));
    if (!accepted.length) {
      return;
    }
    setSaving(true);
    setError("");
    setMessage("");
    try {
      const collections = accepted.map((item) => ({
        shipment_date: selectedDate,
        week: isoWeekNumber(selectedDate),
        day_name: dutchDayName(selectedDate),
        customer_id: item.customer_id,
        customer_name: item.customer_name,
        collection_type: item.collection_type,
        city_name: item.city_name,
        border_crossing: item.border_crossing,
        hub_code: item.hub_code,
        remark: item.remark,
        pd_form: item.pd_form,
        re_export: item.re_export,
        pd_type: item.pd_type,
        pd_code: item.pd_code,
      }));
      const payload = await apiJson("/api/ukdocs-print/collections", {
        method: "POST",
        body: JSON.stringify({ collections }),
      });
      setState((current) => ({ ...current, print_collections: payload.print_collections }));
      setMessage(`${payload.created.length} row(s) accepted from last week's proposal.`);
    } catch (acceptError) {
      setError(acceptError.message);
    } finally {
      setSaving(false);
    }
  }

  function emptyRowDraft() {
    return {
      id: "",
      shipment_date: selectedDate,
      week: isoWeekNumber(selectedDate),
      day_name: dutchDayName(selectedDate),
      customer_name: "",
      customer_id: "",
      city_name: "",
      border_crossing: "",
      hub_code: "",
      remark: "",
      pd_form: "",
      re_export: "",
      pd_type: "",
      pd_code: "",
      reference_connect: "",
      pd_keuring_done: false,
      pd_keuring_made_by: "",
      truck_number: "",
      trailer_number: "",
    };
  }

  function referenceAutofillForCity(cityName) {
    const match = pdReference.find((item) => item.city_name.trim().toLowerCase() === String(cityName || "").trim().toLowerCase());
    if (!match) {
      return {};
    }
    // pd_form is deliberately never autofilled -- it changes day to day, so
    // it always needs a fresh manual entry regardless of what this city's
    // template last saw.
    return {
      pd_type: match.pd_type || "",
      hub_code: match.hub_codes || "",
      border_crossing: match.border_crossing || "",
      re_export: match.re_export || "",
      pd_code: match.pd_code || "",
    };
  }

  function updateRowDraftField(key, value) {
    setDuplicateMatch(null);
    setRowDraft((current) => {
      let next = { ...current, [key]: value };
      if (key === "city_name") {
        // City can bring its own hub code/border crossing/etc from the
        // reference table -- customer is always picked explicitly from the
        // Customer dropdown below, never guessed from city/hub/remark.
        next = { ...next, ...referenceAutofillForCity(value) };
      }
      return next;
    });
  }

  // Mirrors the server's ukdocsPrintCollectionGroupKey: rows sharing date +
  // city + hub + remark + type are merged into one shipment on every sheet
  // sync/dedupe, so this is exactly the key a new row would be joined on.
  function pdShipmentGroupKey(row) {
    const token = (value) => String(value || "").toUpperCase().replace(/[^A-Z0-9]/g, "");
    const type = row.collection_type || (String(row.city_name || "").trim().toUpperCase() === "HONSELERSDIJK" ? "stock_control" : "export");
    return [String(row.shipment_date || "").slice(0, 10), token(row.city_name), token(row.hub_code), token(row.remark), token(type)].join("|");
  }

  // Remark is part of that key and round-trips through the sheet, so a
  // distinct "deel N" remark is what keeps a split shipment separate.
  function nextSeparateShipmentRemark(draft) {
    const base = String(draft.remark || "").trim().replace(/^-$/, "");
    const takenKeys = new Set(dayRows.map(pdShipmentGroupKey));
    for (let part = 2; part < 100; part += 1) {
      const remark = base ? `${base} deel ${part}` : `deel ${part}`;
      if (!takenKeys.has(pdShipmentGroupKey({ ...draft, remark }))) {
        return remark;
      }
    }
    return `${base} deel ${Date.now()}`.trim();
  }

  async function saveRow(choice) {
    if (!rowDraft) {
      return;
    }
    if (!rowDraft.customer_id || !customers.some((item) => item.id === rowDraft.customer_id)) {
      setError("Select a customer before saving.");
      return;
    }
    let draftToSave = rowDraft;
    if (!rowDraft.id && !choice) {
      const draftKey = pdShipmentGroupKey(rowDraft);
      const match = dayRows.find((item) => pdShipmentGroupKey(item) === draftKey);
      if (match) {
        setDuplicateMatch(match);
        return;
      }
    }
    if (choice === "separate") {
      draftToSave = { ...rowDraft, remark: nextSeparateShipmentRemark(rowDraft) };
    }
    setDuplicateMatch(null);
    setSaving(true);
    setError("");
    setMessage("");
    try {
      if (draftToSave.id) {
        const payload = await apiJson(`/api/ukdocs-print/collections/${encodeURIComponent(draftToSave.id)}`, {
          method: "PATCH",
          body: JSON.stringify(draftToSave),
        });
        setState((current) => ({ ...current, print_collections: payload.print_collections }));
        setMessage("Row updated.");
      } else {
        const payload = await apiJson("/api/ukdocs-print/collections", {
          method: "POST",
          body: JSON.stringify({ collections: [draftToSave] }),
        });
        setState((current) => ({ ...current, print_collections: payload.print_collections }));
        setMessage(choice === "separate"
          ? `Row added as a separate shipment (remark "${draftToSave.remark}").`
          : choice === "join" ? "Row added and joined with the existing shipment." : "Row added.");
      }
      setRowDraft(null);
    } catch (saveError) {
      setError(saveError.message);
    } finally {
      setSaving(false);
    }
  }

  async function deleteRow(rowId) {
    if (!window.confirm("Delete this PD Keuring row?")) {
      return;
    }
    setSaving(true);
    setError("");
    setMessage("");
    try {
      const payload = await apiJson(`/api/ukdocs-print/collections/${encodeURIComponent(rowId)}`, { method: "DELETE" });
      setState((current) => ({ ...current, print_collections: payload.print_collections }));
      setMessage("Row deleted.");
    } catch (deleteError) {
      setError(deleteError.message);
    } finally {
      setSaving(false);
    }
  }

  const INLINE_EDIT_FIELDS = ["transport_mode", "reference_connect", "expected_boxes", "expected_pieces", "truck_number", "trailer_number"];

  function inlineFieldValue(row, field) {
    const edits = inlineEdits[row.id];
    return edits && field in edits ? edits[field] : (row[field] || "");
  }

  function updateInlineField(rowId, field, value) {
    setInlineEdits((current) => ({ ...current, [rowId]: { ...current[rowId], [field]: value } }));
  }

  function isRowDirty(row) {
    const edits = inlineEdits[row.id];
    if (!edits) {
      return false;
    }
    return INLINE_EDIT_FIELDS.some((field) => field in edits && edits[field] !== (row[field] || ""));
  }

  async function saveInlineEdits(row) {
    const edits = inlineEdits[row.id];
    if (!edits) {
      return;
    }
    setSaving(true);
    setError("");
    setMessage("");
    try {
      const payload = await apiJson(`/api/ukdocs-print/collections/${encodeURIComponent(row.id)}`, {
        method: "PATCH",
        body: JSON.stringify(edits),
      });
      setState((current) => ({ ...current, print_collections: payload.print_collections }));
      setInlineEdits((current) => {
        const next = { ...current };
        delete next[row.id];
        return next;
      });
      setMessage("Row updated.");
    } catch (saveError) {
      setError(saveError.message);
    } finally {
      setSaving(false);
    }
  }

  async function saveStatePatch(patch, successMessage) {
    setSaving(true);
    setError("");
    setMessage("");
    try {
      const payload = await apiJson("/api/ukdocs/state", {
        method: "PATCH",
        body: JSON.stringify(patch),
      });
      setState(payload.state);
      setMessage(successMessage);
    } catch (saveError) {
      setError(saveError.message);
    } finally {
      setSaving(false);
    }
  }

  async function syncDropdownOptions() {
    setSaving(true);
    setError("");
    setMessage("");
    try {
      const payload = await apiJson("/api/ukdocs-print/pd-keuring/sync-options", { method: "POST" });
      setState((current) => ({ ...current, pd_dropdown_options: payload.pd_dropdown_options }));
      setMessage("Dropdown options refreshed from the \"data\" tab.");
    } catch (syncError) {
      setError(syncError.message);
    } finally {
      setSaving(false);
    }
  }

  function saveReferenceEntry() {
    const nextEntry = { ...referenceDraft, id: referenceDraft.id || crypto.randomUUID() };
    const nextReference = referenceDraft.id
      ? pdReference.map((item) => (item.id === referenceDraft.id ? nextEntry : item))
      : [nextEntry, ...pdReference];
    saveStatePatch({ pd_reference: nextReference }, referenceDraft.id ? "Reference entry updated." : "Reference entry added.");
    setReferenceDraft(emptyUkdocsPdReferenceEntry());
  }

  function startEditReferenceEntry(entry) {
    setReferenceDraft(entry);
  }

  function deleteReferenceEntry(entryId) {
    if (!window.confirm("Delete this reference entry?")) {
      return;
    }
    saveStatePatch({ pd_reference: pdReference.filter((item) => item.id !== entryId) }, "Reference entry deleted.");
  }

  async function buildReferenceFromHistory() {
    if (!window.confirm("Build/update city templates from every historical row imported so far? This overwrites hub codes/border crossing/re-export/type/PD code per city with whatever's most common in the history -- PD form letter is left untouched.")) {
      return;
    }
    setBuildingReferenceFromHistory(true);
    setError("");
    setMessage("");
    try {
      const payload = await apiJson("/api/ukdocs-print/pd-keuring/build-reference-from-history", { method: "POST" });
      setState((current) => ({ ...current, pd_reference: payload.pd_reference }));
      setMessage(`Templates built from ${payload.cities_processed} cities: ${payload.created} created, ${payload.updated} updated.`);
    } catch (buildError) {
      setError(buildError.message);
    } finally {
      setBuildingReferenceFromHistory(false);
    }
  }

  async function runBackfill() {
    const sheetNames = backfillIncludeOud ? ["PD planning", "OUD PD Planning 2025"] : ["PD planning"];
    if (!window.confirm(`Import all historical rows from ${sheetNames.join(" and ")}? This can be run again safely -- it only adds or updates matching rows.`)) {
      return;
    }
    setBackfillBusy(true);
    setError("");
    setMessage("");
    setBackfillResult(null);
    try {
      const payload = await apiJson("/api/ukdocs-print/pd-keuring/backfill-history", {
        method: "POST",
        body: JSON.stringify({ sheet_names: sheetNames }),
      });
      setBackfillResult(payload);
      setMessage(`Backfill complete: ${payload.total_imported} imported, ${payload.total_updated} updated.`);
    } catch (backfillError) {
      setError(backfillError.message);
    } finally {
      setBackfillBusy(false);
    }
  }

  if (loading) {
    return <div className="notice">Loading PD Keuring workspace...</div>;
  }

  return (
    <section className="overview-stack ukdocs-page">
      <div className="tab-strip">
        {[
          ["planning", "Day planning"],
          ["reference", "Data"],
        ].map(([key, label]) => (
          <button key={key} type="button" className={activeMenu === key ? "active" : ""} onClick={() => setActiveMenu(key)}>{label}</button>
        ))}
      </div>

      {message && <div className="notice">{message}</div>}
      {error && <div className="notice danger">{error}</div>}

      {activeMenu === "planning" && (
        <div className="data-table-card ukdocs-stack">
          <div className="section-header"><h2>Day planning</h2></div>

          <div className="overview-filters">
            <label>
              <span>Date</span>
              <input type="date" value={selectedDate} onChange={(event) => { setSelectedDate(event.target.value); setRowDraft(null); }} />
            </label>
          </div>
          <div className="row-actions spread-actions">
            <button type="button" onClick={syncDropdownOptions} disabled={saving}>Sync dropdown options from data tab</button>
          </div>

          {rowDraft && (
            <>
              <div className="section-header"><h3>{rowDraft.id ? "Edit row" : "Add row"}</h3></div>
              {!pdDropdownOptions.cities?.length && (
                <div className="notice">No dropdown suggestions loaded yet -- use "Sync dropdown options from data tab" below to pull the city/code/type lists from the spreadsheet.</div>
              )}
              <div className="form-grid">
                <label>
                  <span>City</span>
                  <UsedValuesCombo value={rowDraft.city_name} options={usedOptions.city_name} onChange={(next) => updateRowDraftField("city_name", next)} />
                </label>
                <label>
                  <span>Border crossing</span>
                  <UsedValuesCombo value={rowDraft.border_crossing} options={usedOptions.border_crossing} onChange={(next) => updateRowDraftField("border_crossing", next)} />
                </label>
                <label>
                  <span>Hub code</span>
                  <UsedValuesCombo value={rowDraft.hub_code} options={usedOptions.hub_code} onChange={(next) => updateRowDraftField("hub_code", next)} />
                </label>
                <label>
                  <span>Remark</span>
                  <UsedValuesCombo value={rowDraft.remark} options={usedOptions.remark} onChange={(next) => updateRowDraftField("remark", next)} />
                </label>
                <label>
                  <span>PD form</span>
                  <UsedValuesCombo value={rowDraft.pd_form} options={usedOptions.pd_form} onChange={(next) => updateRowDraftField("pd_form", next)} />
                </label>
                <label>
                  <span>Re-export</span>
                  <UsedValuesCombo value={rowDraft.re_export} options={usedOptions.re_export} onChange={(next) => updateRowDraftField("re_export", next)} />
                </label>
                <label>
                  <span>Type</span>
                  <UsedValuesCombo value={rowDraft.pd_type} options={usedOptions.pd_type} onChange={(next) => updateRowDraftField("pd_type", next)} />
                </label>
                <label>
                  <span>PD code</span>
                  <UsedValuesCombo value={rowDraft.pd_code} options={usedOptions.pd_code} onChange={(next) => updateRowDraftField("pd_code", next)} />
                </label>
                <label>
                  <span>Reference connect</span>
                  <input value={rowDraft.reference_connect || ""} onChange={(event) => updateRowDraftField("reference_connect", event.target.value)} />
                </label>
                <label>
                  <span>Customer</span>
                  <select
                    value={rowDraft.customer_id || ""}
                    onChange={(event) => {
                      const chosen = customers.find((item) => item.id === event.target.value);
                      setRowDraft((current) => ({
                        ...current,
                        customer_id: chosen?.id || "",
                        customer_name: chosen?.customer_name || "",
                        // Truck or airplane: the customer's default (UKdocs
                        // customer settings), still changeable below.
                        ...(chosen ? { transport_mode: chosen.default_transport_mode || "Truck" } : {}),
                      }));
                    }}
                  >
                    <option value="">-- Select customer --</option>
                    {customers.map((customer) => <option key={customer.id} value={customer.id}>{customer.customer_name}</option>)}
                  </select>
                </label>
                <label>
                  <span>Keuring made by</span>
                  <UsedValuesCombo value={rowDraft.pd_keuring_made_by} options={usedOptions.pd_keuring_made_by} onChange={(next) => updateRowDraftField("pd_keuring_made_by", next)} />
                </label>
                <label>
                  <span>Transport</span>
                  <select value={rowDraft.transport_mode || "Truck"} onChange={(event) => updateRowDraftField("transport_mode", event.target.value)}>
                    <option value="Truck">Truck</option>
                    <option value="Airplane">Airplane</option>
                  </select>
                </label>
                <label>
                  <span>Truck number</span>
                  <input value={rowDraft.truck_number || ""} onChange={(event) => updateRowDraftField("truck_number", event.target.value)} placeholder="For example: 1 BHM" />
                </label>
                <label>
                  <span>Truck / trailer licence plate</span>
                  <input value={rowDraft.trailer_number || ""} onChange={(event) => updateRowDraftField("trailer_number", event.target.value)} />
                </label>
              </div>
              <label className="checkbox-label">
                <input type="checkbox" checked={rowDraft.pd_keuring_done === true} onChange={(event) => updateRowDraftField("pd_keuring_done", event.target.checked)} />
                <span>Done</span>
              </label>
              {rowDraft.customer_id && customers.some((item) => item.id === rowDraft.customer_id) ? (
                <span className="ukdocs-status-badge success">Matched customer: {rowDraft.customer_name}</span>
              ) : (
                <span className="ukdocs-status-badge danger">No customer selected -- pick one from the Customer dropdown before saving.</span>
              )}
              {duplicateMatch && (
                <div className="notice">
                  This matches an existing shipment for {selectedDate}: {duplicateMatch.city_name || "-"} / {duplicateMatch.hub_code || "-"}{duplicateMatch.remark ? ` / ${duplicateMatch.remark}` : ""} ({duplicateMatch.customer_name || "no customer"}{duplicateMatch.reference_connect ? `, ref ${duplicateMatch.reference_connect}` : ""}).
                  {" "}Join them together, or treat this as a separate shipment (it gets remark "{nextSeparateShipmentRemark(rowDraft)}" so it stays its own row in the app and the sheet)?
                  <div className="row-actions">
                    <button type="button" onClick={() => saveRow("join")} disabled={saving}>Join with existing</button>
                    <button type="button" className="primary" onClick={() => saveRow("separate")} disabled={saving}>Separate shipment</button>
                    <button type="button" onClick={() => setDuplicateMatch(null)} disabled={saving}>Back</button>
                  </div>
                </div>
              )}
              <div className="row-actions spread-actions">
                <button type="button" className="primary" onClick={() => saveRow()} disabled={saving || !!duplicateMatch || !rowDraft.customer_id || !customers.some((item) => item.id === rowDraft.customer_id)}>{rowDraft.id ? "Update row" : "Add row"}</button>
                <button type="button" onClick={() => { setRowDraft(null); setDuplicateMatch(null); }} disabled={saving}>Cancel</button>
              </div>
            </>
          )}

          {showProposals && !rowDraft && (
            <>
              <div className="section-header"><h3>Proposed from {lastWeekDate} (last week)</h3></div>
              <div className="notice">No rows yet for {selectedDate}. These ran on the same weekday last week -- checked ones will be added for today, with reference connect and done/made-by left blank to fill in fresh.</div>
              <div className="table-wrap">
                <table className="data-table">
                  <thead>
                    <tr>
                      <th></th>
                      <th>City</th>
                      <th>Hub</th>
                      <th>Border</th>
                      <th>Type</th>
                      <th>PD form</th>
                      <th>Customer</th>
                    </tr>
                  </thead>
                  <tbody>
                    {lastWeekRows.map((row) => (
                      <tr key={row.id}>
                        <td><input type="checkbox" checked={proposalSelectedIds.includes(row.id)} onChange={() => toggleProposalSelected(row.id)} /></td>
                        <td>{row.city_name || "-"}</td>
                        <td>{row.hub_code || "-"}</td>
                        <td>{row.border_crossing || "-"}</td>
                        <td>{row.pd_type || "-"}</td>
                        <td>{row.pd_form || "-"}</td>
                        <td>{row.customer_name || "-"}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <div className="row-actions spread-actions">
                <button type="button" className="primary" onClick={acceptProposals} disabled={saving || !proposalSelectedIds.length}>Accept selected for {selectedDate}</button>
              </div>
            </>
          )}

          {!rowDraft && (
            <div className="row-actions spread-actions">
              <button type="button" className="primary" onClick={() => { setDuplicateMatch(null); setRowDraft(emptyRowDraft()); }}>Add row for {selectedDate}</button>
            </div>
          )}

          <div className="table-wrap">
            <table className="data-table">
              <thead>
                <tr>
                  <th>City</th>
                  <th>Border</th>
                  <th>Hub</th>
                  <th>Remark</th>
                  <th>PD form</th>
                  <th>Type</th>
                  <th>PD code</th>
                  <th>Reference connect</th>
                  <th>Customer</th>
                  <th>Transport</th>
                  <th>Truck number</th>
                  <th>Truck / trailer licence plate</th>
                  <th>Boxes</th>
                  <th>Pieces</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {dayRows.map((row) => {
                  const dirty = isRowDirty(row);
                  return (
                    <tr key={row.id} id={`pd-row-${row.id}`} className={row.id === stepFocusRowId ? "step-plan-row" : undefined}>
                      <td>{row.city_name || "-"}</td>
                      <td>{row.border_crossing || "-"}</td>
                      <td>{row.hub_code || "-"}</td>
                      <td>{row.remark || "-"}</td>
                      <td>{row.pd_form || "-"}</td>
                      <td>{row.pd_type || "-"}</td>
                      <td>{row.pd_code || "-"}</td>
                      <td><input className={stepNeeded(row, "reference_connect") ? "step-plan-needed" : undefined} value={inlineFieldValue(row, "reference_connect")} onChange={(event) => updateInlineField(row.id, "reference_connect", event.target.value)} /></td>
                      <td>{row.customer_id && customers.some((item) => item.id === row.customer_id) ? (row.customer_name || "-") : <span className="ukdocs-status-badge danger">No customer picked</span>}</td>
                      <td>
                        <select value={inlineFieldValue(row, "transport_mode") || "Truck"} onChange={(event) => updateInlineField(row.id, "transport_mode", event.target.value)}>
                          <option value="Truck">Truck</option>
                          <option value="Airplane">Airplane</option>
                        </select>
                      </td>
                      <td><input className={stepNeeded(row, "truck_number") ? "step-plan-needed" : undefined} value={inlineFieldValue(row, "truck_number")} onChange={(event) => updateInlineField(row.id, "truck_number", event.target.value)} placeholder="Truck number" /></td>
                      <td><input className={stepNeeded(row, "trailer_number") ? "step-plan-needed" : undefined} value={inlineFieldValue(row, "trailer_number")} onChange={(event) => updateInlineField(row.id, "trailer_number", event.target.value)} placeholder="Licence plate" /></td>
                      <td><input value={inlineFieldValue(row, "expected_boxes")} onChange={(event) => updateInlineField(row.id, "expected_boxes", event.target.value)} placeholder="Boxes" /></td>
                      <td><input className={stepNeeded(row, "expected_pieces") ? "step-plan-needed" : undefined} value={inlineFieldValue(row, "expected_pieces")} onChange={(event) => updateInlineField(row.id, "expected_pieces", event.target.value)} placeholder="Pieces" /></td>
                      <td className="row-actions">
                        {dirty && <button type="button" className="primary" onClick={() => saveInlineEdits(row)} disabled={saving}>Save</button>}
                        <button type="button" onClick={() => setRowDraft({ ...row })}>Edit</button>
                        <button type="button" onClick={() => deleteRow(row.id)}>Delete</button>
                      </td>
                    </tr>
                  );
                })}
                {!dayRows.length && <tr><td colSpan="15">No PD Keuring rows for {selectedDate} yet.</td></tr>}
              </tbody>
            </table>
          </div>

          {canManageSettings && (
            <>
              <div className="section-header"><h3>Historical backfill</h3></div>
              <div className="notice">
                One-time import of every historical row from the PD keuringen spreadsheet, so PD Keuring's history doesn't depend on the spreadsheet staying available. Safe to run more than once -- it only adds or updates matching rows, never duplicates.
              </div>
              <label className="checkbox-label">
                <input type="checkbox" checked={backfillIncludeOud} onChange={(event) => setBackfillIncludeOud(event.target.checked)} />
                <span>Also include "OUD PD Planning 2025" (older archived history -- some rows there have known data-quality quirks, e.g. a few border-crossing values are stray numbers instead of text)</span>
              </label>
              <div className="row-actions spread-actions">
                <button type="button" onClick={runBackfill} disabled={backfillBusy}>{backfillBusy ? "Running..." : "Run historical backfill"}</button>
              </div>
              {backfillResult && (
                <div className="table-wrap">
                  <table className="data-table">
                    <thead><tr><th>Tab</th><th>Imported</th><th>Updated</th></tr></thead>
                    <tbody>
                      {backfillResult.tabs.map((tab) => (
                        <tr key={tab.sheet_name}><td>{tab.sheet_name}</td><td>{tab.imported}</td><td>{tab.updated}</td></tr>
                      ))}
                    </tbody>
                  </table>
                </div>
              )}
            </>
          )}
        </div>
      )}

      {activeMenu === "reference" && (
        <div className="data-table-card ukdocs-stack">
          <div className="section-header"><h2>Data</h2></div>
          <div className="notice">Per-city templates used to autofill a new PD Keuring row when you pick its city -- hub codes, border crossing, re-export, type, and PD code. PD form letter changes daily and is never auto-applied, kept here for reference only.</div>
          <div className="row-actions spread-actions">
            <button type="button" onClick={buildReferenceFromHistory} disabled={buildingReferenceFromHistory}>
              {buildingReferenceFromHistory ? "Building..." : "Build templates from history"}
            </button>
          </div>
          <div className="form-grid">
            {UKDOCS_PD_REFERENCE_FIELDS.map(([key, label]) => (
              <label key={key}>
                <span>{label}</span>
                <input value={referenceDraft[key] || ""} onChange={(event) => setReferenceDraft({ ...referenceDraft, [key]: event.target.value })} />
              </label>
            ))}
          </div>
          <div className="row-actions spread-actions">
            <button type="button" className="primary" onClick={saveReferenceEntry} disabled={saving}>{referenceDraft.id ? "Update entry" : "Add entry"}</button>
            <button type="button" onClick={() => setReferenceDraft(emptyUkdocsPdReferenceEntry())} disabled={saving}>Clear form</button>
          </div>
          <div className="table-wrap">
            <table className="data-table">
              <thead>
                <tr>
                  <th>City</th>
                  <th>Code</th>
                  <th>Hub codes</th>
                  <th>Border crossing</th>
                  <th>Re-export</th>
                  <th>Type</th>
                  <th>PD code</th>
                  <th>PD form letter (ref only)</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {pdReference.map((entry) => (
                  <tr key={entry.id}>
                    <td>{entry.city_name}</td>
                    <td>{entry.code}</td>
                    <td>{entry.hub_codes}</td>
                    <td>{entry.border_crossing}</td>
                    <td>{entry.re_export}</td>
                    <td>{entry.pd_type}</td>
                    <td>{entry.pd_code}</td>
                    <td>{entry.pd_form_letter}</td>
                    <td className="row-actions">
                      <button type="button" onClick={() => startEditReferenceEntry(entry)}>Edit</button>
                      <button type="button" onClick={() => deleteReferenceEntry(entry.id)}>Delete</button>
                    </td>
                  </tr>
                ))}
                {!pdReference.length && <tr><td colSpan="9">No reference entries saved yet -- try "Build templates from history" if you've already run the historical backfill.</td></tr>}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </section>
  );
}

